Definition sail_cacheop_encode (x : cacheop) := match x with
  | CB_manage x' => encode (0, encode x')
  | CB_zero x' => encode (1, encode x')
  | CB_prefetch x' => encode (2, encode x') end.
Definition sail_cacheop_decode x : option cacheop := match decode x with
  | Some (0, x') => CB_manage <$> decode x'
  | Some (1, x') => CB_zero <$> decode x'
  | Some (2, x') => CB_prefetch <$> decode x'
  | _ => None end.
Lemma sail_cacheop_decode_encode : forall (x : cacheop), sail_cacheop_decode (sail_cacheop_encode x)
   = Some x.
Proof.
  unfold sail_cacheop_decode, sail_cacheop_encode;
  intros [x|x|x]; rewrite !decode_encode; reflexivity.
Qed.

