Definition sail_MemoryAccessType_encode {a : Type} `{Countable a} (x : (MemoryAccessType a))
  := match x with
  | Load x' => encode (0, encode x')
  | Store x' => encode (1, encode x')
  | LoadReserved x' => encode (2, encode x')
  | LoadExecute x' => encode (3, encode x')
  | StoreConditional x' => encode (4, encode x')
  | Atomic x' => encode (5, encode x')
  | InstructionFetch x' => encode (6, encode x')
  | CacheAccess x' => encode (7, encode x') end.
Definition sail_MemoryAccessType_decode {a : Type} `{Countable a} x : option (MemoryAccessType a)
  := match decode x with
  | Some (0, x') => Load <$> decode x'
  | Some (1, x') => Store <$> decode x'
  | Some (2, x') => LoadReserved <$> decode x'
  | Some (3, x') => LoadExecute <$> decode x'
  | Some (4, x') => StoreConditional <$> decode x'
  | Some (5, x') => Atomic <$> decode x'
  | Some (6, x') => InstructionFetch <$> decode x'
  | Some (7, x') => CacheAccess <$> decode x'
  | _ => None end.
