Inductive breakpoint_cause := Brk_Software | Brk_Hardware.
Definition num_of_breakpoint_cause (arg_ : breakpoint_cause) : Z :=
   match arg_ with | Brk_Software => 0 | Brk_Hardware => 1 end.

Definition breakpoint_cause_of_num (arg_ : Z) (*(0 <=? arg_) && (arg_ <=? 1)*) : breakpoint_cause :=
   let l__0 := arg_ in
   if Z.eqb (l__0) (0) then Brk_Software
   else Brk_Hardware.

Lemma breakpoint_cause_num_of_roundtrip (x : breakpoint_cause) : breakpoint_cause_of_num (num_of_breakpoint_cause x) = x.
  destruct x; reflexivity.
Qed.
Lemma num_of_breakpoint_cause_injective (x y : breakpoint_cause) : num_of_breakpoint_cause x = num_of_breakpoint_cause y -> x = y.
  intro.
  rewrite <- (breakpoint_cause_num_of_roundtrip x).
  rewrite <- (breakpoint_cause_num_of_roundtrip y).
  congruence.
Qed.
Definition breakpoint_cause_eq_dec (x y : breakpoint_cause) : {x = y} + {x <> y}.
  refine (match Z.eq_dec (num_of_breakpoint_cause x) (num_of_breakpoint_cause y) with
  | left e => left (num_of_breakpoint_cause_injective x y e)
  | right ne => right _
  end).
  congruence.
Defined.
Definition breakpoint_cause_beq (x y : breakpoint_cause) : bool :=
  Z.eqb (num_of_breakpoint_cause x) (num_of_breakpoint_cause y).
Lemma breakpoint_cause_beq_iff x y : breakpoint_cause_beq x y = true <-> x = y.
  unfold breakpoint_cause_beq.
  rewrite Z.eqb_eq.
  split; [apply num_of_breakpoint_cause_injective | congruence].
Qed.
Lemma breakpoint_cause_beq_refl x : breakpoint_cause_beq x x = true.
apply breakpoint_cause_beq_iff; reflexivity.
Qed.
#[export]
Instance Decidable_eq_breakpoint_cause : EqDecision breakpoint_cause := breakpoint_cause_eq_dec.
#[export]
Instance Countable_breakpoint_cause : Countable breakpoint_cause.
refine {|
  encode x := encode (num_of_breakpoint_cause x);
  decode x := z ← decode x; mret (breakpoint_cause_of_num z);
|}.
abstract (
  intro s; rewrite decode_encode;
  simpl;
  rewrite breakpoint_cause_num_of_roundtrip;
  reflexivity).
Defined.
#[export]
Instance dummy_breakpoint_cause : Inhabited breakpoint_cause := { inhabitant := Brk_Software }.


