Inductive bop := BEQ | BNE | BLT | BGE | BLTU | BGEU.
Definition num_of_bop (arg_ : bop) : Z :=
   match arg_ with | BEQ => 0 | BNE => 1 | BLT => 2 | BGE => 3 | BLTU => 4 | BGEU => 5 end.

Definition bop_of_num (arg_ : Z) (*(0 <=? arg_) && (arg_ <=? 5)*) : bop :=
   let l__0 := arg_ in
   if Z.eqb (l__0) (0) then BEQ
   else if Z.eqb (l__0) (1) then BNE
   else if Z.eqb (l__0) (2) then BLT
   else if Z.eqb (l__0) (3) then BGE
   else if Z.eqb (l__0) (4) then BLTU
   else BGEU.

Lemma bop_num_of_roundtrip (x : bop) : bop_of_num (num_of_bop x) = x.
  destruct x; reflexivity.
Qed.
Lemma num_of_bop_injective (x y : bop) : num_of_bop x = num_of_bop y -> x = y.
  intro.
  rewrite <- (bop_num_of_roundtrip x).
  rewrite <- (bop_num_of_roundtrip y).
  congruence.
Qed.
Definition bop_eq_dec (x y : bop) : {x = y} + {x <> y}.
  refine (match Z.eq_dec (num_of_bop x) (num_of_bop y) with
  | left e => left (num_of_bop_injective x y e)
  | right ne => right _
  end).
  congruence.
Defined.
Definition bop_beq (x y : bop) : bool :=
  Z.eqb (num_of_bop x) (num_of_bop y).
Lemma bop_beq_iff x y : bop_beq x y = true <-> x = y.
  unfold bop_beq.
  rewrite Z.eqb_eq.
  split; [apply num_of_bop_injective | congruence].
Qed.
Lemma bop_beq_refl x : bop_beq x x = true.
apply bop_beq_iff; reflexivity.
Qed.
#[export]
Instance Decidable_eq_bop : EqDecision bop := bop_eq_dec.
#[export]
Instance Countable_bop : Countable bop.
refine {|
  encode x := encode (num_of_bop x);
  decode x := z ← decode x; mret (bop_of_num z);
|}.
abstract (
  intro s; rewrite decode_encode;
  simpl;
  rewrite bop_num_of_roundtrip;
  reflexivity).
Defined.
#[export]
Instance dummy_bop : Inhabited bop := { inhabitant := BEQ }.


