Inductive rounding_mode := RM_RNE | RM_RTZ | RM_RDN | RM_RUP | RM_RMM | RM_DYN.
Definition num_of_rounding_mode (arg_ : rounding_mode) : Z :=
   match arg_ with
   | RM_RNE => 0
   | RM_RTZ => 1
   | RM_RDN => 2
   | RM_RUP => 3
   | RM_RMM => 4
   | RM_DYN => 5
   end.

Definition rounding_mode_of_num (arg_ : Z) (*(0 <=? arg_) && (arg_ <=? 5)*) : rounding_mode :=
   let l__0 := arg_ in
   if Z.eqb (l__0) (0) then RM_RNE
   else if Z.eqb (l__0) (1) then RM_RTZ
   else if Z.eqb (l__0) (2) then RM_RDN
   else if Z.eqb (l__0) (3) then RM_RUP
   else if Z.eqb (l__0) (4) then RM_RMM
   else RM_DYN.

Lemma rounding_mode_num_of_roundtrip (x : rounding_mode) : rounding_mode_of_num (num_of_rounding_mode x) = x.
  destruct x; reflexivity.
Qed.
Lemma num_of_rounding_mode_injective (x y : rounding_mode) : num_of_rounding_mode x = num_of_rounding_mode y -> x = y.
  intro.
  rewrite <- (rounding_mode_num_of_roundtrip x).
  rewrite <- (rounding_mode_num_of_roundtrip y).
  congruence.
Qed.
Definition rounding_mode_eq_dec (x y : rounding_mode) : {x = y} + {x <> y}.
  refine (match Z.eq_dec (num_of_rounding_mode x) (num_of_rounding_mode y) with
  | left e => left (num_of_rounding_mode_injective x y e)
  | right ne => right _
  end).
  congruence.
Defined.
Definition rounding_mode_beq (x y : rounding_mode) : bool :=
  Z.eqb (num_of_rounding_mode x) (num_of_rounding_mode y).
Lemma rounding_mode_beq_iff x y : rounding_mode_beq x y = true <-> x = y.
  unfold rounding_mode_beq.
  rewrite Z.eqb_eq.
  split; [apply num_of_rounding_mode_injective | congruence].
Qed.
Lemma rounding_mode_beq_refl x : rounding_mode_beq x x = true.
apply rounding_mode_beq_iff; reflexivity.
Qed.
#[export]
Instance Decidable_eq_rounding_mode : EqDecision rounding_mode := rounding_mode_eq_dec.
#[export]
Instance Countable_rounding_mode : Countable rounding_mode.
refine {|
  encode x := encode (num_of_rounding_mode x);
  decode x := z ← decode x; mret (rounding_mode_of_num z);
|}.
abstract (
  intro s; rewrite decode_encode;
