Inductive vxmfunct6 := VXM_VMADC | VXM_VMSBC.
Definition num_of_vxmfunct6 (arg_ : vxmfunct6) : Z :=
   match arg_ with | VXM_VMADC => 0 | VXM_VMSBC => 1 end.

Definition vxmfunct6_of_num (arg_ : Z) (*(0 <=? arg_) && (arg_ <=? 1)*) : vxmfunct6 :=
   let l__0 := arg_ in
   if Z.eqb (l__0) (0) then VXM_VMADC
   else VXM_VMSBC.

Lemma vxmfunct6_num_of_roundtrip (x : vxmfunct6) : vxmfunct6_of_num (num_of_vxmfunct6 x) = x.
  destruct x; reflexivity.
Qed.
Lemma num_of_vxmfunct6_injective (x y : vxmfunct6) : num_of_vxmfunct6 x = num_of_vxmfunct6 y -> x = y.
  intro.
  rewrite <- (vxmfunct6_num_of_roundtrip x).
  rewrite <- (vxmfunct6_num_of_roundtrip y).
  congruence.
Qed.
Definition vxmfunct6_eq_dec (x y : vxmfunct6) : {x = y} + {x <> y}.
  refine (match Z.eq_dec (num_of_vxmfunct6 x) (num_of_vxmfunct6 y) with
  | left e => left (num_of_vxmfunct6_injective x y e)
  | right ne => right _
  end).
  congruence.
Defined.
Definition vxmfunct6_beq (x y : vxmfunct6) : bool :=
  Z.eqb (num_of_vxmfunct6 x) (num_of_vxmfunct6 y).
Lemma vxmfunct6_beq_iff x y : vxmfunct6_beq x y = true <-> x = y.
  unfold vxmfunct6_beq.
  rewrite Z.eqb_eq.
  split; [apply num_of_vxmfunct6_injective | congruence].
Qed.
Lemma vxmfunct6_beq_refl x : vxmfunct6_beq x x = true.
apply vxmfunct6_beq_iff; reflexivity.
Qed.
#[export]
Instance Decidable_eq_vxmfunct6 : EqDecision vxmfunct6 := vxmfunct6_eq_dec.
#[export]
Instance Countable_vxmfunct6 : Countable vxmfunct6.
refine {|
  encode x := encode (num_of_vxmfunct6 x);
  decode x := z ← decode x; mret (vxmfunct6_of_num z);
|}.
abstract (
  intro s; rewrite decode_encode;
  simpl;
  rewrite vxmfunct6_num_of_roundtrip;
  reflexivity).
Defined.
