  rewrite Z.eqb_eq.
  split; [apply num_of_zilx_mode_injective | congruence].
Qed.
Lemma zilx_mode_beq_refl x : zilx_mode_beq x x = true.
apply zilx_mode_beq_iff; reflexivity.
Qed.
#[export]
Instance Decidable_eq_zilx_mode : EqDecision zilx_mode := zilx_mode_eq_dec.
#[export]
Instance Countable_zilx_mode : Countable zilx_mode.
refine {|
  encode x := encode (num_of_zilx_mode x);
  decode x := z ← decode x; mret (zilx_mode_of_num z);
|}.
abstract (
  intro s; rewrite decode_encode;
  simpl;
  rewrite zilx_mode_num_of_roundtrip;
  reflexivity).
Defined.
#[export]
Instance dummy_zilx_mode : Inhabited zilx_mode := { inhabitant := ZILX_UNSCALED }.


Inductive f_un_rm_ff_op_S := FSQRT_S.
Definition num_of_f_un_rm_ff_op_S (arg_ : f_un_rm_ff_op_S) : Z :=
   match arg_ with | FSQRT_S => 0 end.

Definition f_un_rm_ff_op_S_of_num (arg_ : Z) (*(0 <=? arg_) && (arg_ <=? 0)*) : f_un_rm_ff_op_S :=
   match arg_ with | _ => FSQRT_S end.

Lemma f_un_rm_ff_op_S_num_of_roundtrip (x : f_un_rm_ff_op_S) : f_un_rm_ff_op_S_of_num (num_of_f_un_rm_ff_op_S x) = x.
  destruct x; reflexivity.
Qed.
Lemma num_of_f_un_rm_ff_op_S_injective (x y : f_un_rm_ff_op_S) : num_of_f_un_rm_ff_op_S x = num_of_f_un_rm_ff_op_S y -> x = y.
  intro.
  rewrite <- (f_un_rm_ff_op_S_num_of_roundtrip x).
  rewrite <- (f_un_rm_ff_op_S_num_of_roundtrip y).
  congruence.
Qed.
Definition f_un_rm_ff_op_S_eq_dec (x y : f_un_rm_ff_op_S) : {x = y} + {x <> y}.
  refine (match Z.eq_dec (num_of_f_un_rm_ff_op_S x) (num_of_f_un_rm_ff_op_S y) with
  | left e => left (num_of_f_un_rm_ff_op_S_injective x y e)
  | right ne => right _
  end).
  congruence.
Defined.
Definition f_un_rm_ff_op_S_beq (x y : f_un_rm_ff_op_S) : bool :=
  Z.eqb (num_of_f_un_rm_ff_op_S x) (num_of_f_un_rm_ff_op_S y).
Lemma f_un_rm_ff_op_S_beq_iff x y : f_un_rm_ff_op_S_beq x y = true <-> x = y.
  unfold f_un_rm_ff_op_S_beq.
  rewrite Z.eqb_eq.
  split; [apply num_of_f_un_rm_ff_op_S_injective | congruence].
Qed.
Lemma f_un_rm_ff_op_S_beq_refl x : f_un_rm_ff_op_S_beq x x = true.
apply f_un_rm_ff_op_S_beq_iff; reflexivity.
Qed.
#[export]
Instance Decidable_eq_f_un_rm_ff_op_S : EqDecision f_un_rm_ff_op_S := f_un_rm_ff_op_S_eq_dec.
#[export]
Instance Countable_f_un_rm_ff_op_S : Countable f_un_rm_ff_op_S.
refine {|
  encode x := encode (num_of_f_un_rm_ff_op_S x);
  decode x := z ← decode x; mret (f_un_rm_ff_op_S_of_num z);
|}.
abstract (
  intro s; rewrite decode_encode;
  simpl;
  rewrite f_un_rm_ff_op_S_num_of_roundtrip;
  reflexivity).
Defined.
#[export]
Instance dummy_f_un_rm_ff_op_S : Inhabited f_un_rm_ff_op_S := { inhabitant := FSQRT_S }.


Definition half : Type := bits 16.

Definition landing_pad_label : Type := bits 20.

Definition nfields_range (q : Z) : bool := (q >? 0) && (q <=? 8).
#[export] Hint Unfold nfields_range : sail.

Definition nfields : Type := Z.

Definition nfields_range_pow2 (q : Z) : bool := member_Z_list q [1; 2; 4; 8].
#[export] Hint Unfold nfields_range_pow2 : sail.

Definition nfields_pow2 : Type := Z.

Definition shamt_zba : Type := bits 2.

Definition word : Type := bits 32.

Definition word_width_wide : Type := Z.

Inductive wrsop := WRS_STO | WRS_NTO.
Definition num_of_wrsop (arg_ : wrsop) : Z := match arg_ with | WRS_STO => 0 | WRS_NTO => 1 end.

Definition wrsop_of_num (arg_ : Z) (*(0 <=? arg_) && (arg_ <=? 1)*) : wrsop :=
   let l__0 := arg_ in
   if Z.eqb (l__0) (0) then WRS_STO
   else WRS_NTO.

Lemma wrsop_num_of_roundtrip (x : wrsop) : wrsop_of_num (num_of_wrsop x) = x.
  destruct x; reflexivity.
Qed.
Lemma num_of_wrsop_injective (x y : wrsop) : num_of_wrsop x = num_of_wrsop y -> x = y.
  intro.
  rewrite <- (wrsop_num_of_roundtrip x).
  rewrite <- (wrsop_num_of_roundtrip y).
  congruence.
Qed.
Definition wrsop_eq_dec (x y : wrsop) : {x = y} + {x <> y}.
  refine (match Z.eq_dec (num_of_wrsop x) (num_of_wrsop y) with
  | left e => left (num_of_wrsop_injective x y e)
  | right ne => right _
  end).
  congruence.
Defined.
Definition wrsop_beq (x y : wrsop) : bool :=
  Z.eqb (num_of_wrsop x) (num_of_wrsop y).
Lemma wrsop_beq_iff x y : wrsop_beq x y = true <-> x = y.
  unfold wrsop_beq.
  rewrite Z.eqb_eq.
  split; [apply num_of_wrsop_injective | congruence].
Qed.
Lemma wrsop_beq_refl x : wrsop_beq x x = true.
apply wrsop_beq_iff; reflexivity.
Qed.
#[export]
Instance Decidable_eq_wrsop : EqDecision wrsop := wrsop_eq_dec.
#[export]
Instance Countable_wrsop : Countable wrsop.
refine {|
  encode x := encode (num_of_wrsop x);
  decode x := z ← decode x; mret (wrsop_of_num z);
|}.
abstract (
  intro s; rewrite decode_encode;
  simpl;
  rewrite wrsop_num_of_roundtrip;
  reflexivity).
Defined.
#[export]
Instance dummy_wrsop : Inhabited wrsop := { inhabitant := WRS_STO }.


