Inductive Privilege := User | VirtualUser | Supervisor | VirtualSupervisor | Machine.
Definition num_of_Privilege (arg_ : Privilege) : Z :=
   match arg_ with
   | User => 0
   | VirtualUser => 1
   | Supervisor => 2
   | VirtualSupervisor => 3
   | Machine => 4
   end.

Definition Privilege_of_num (arg_ : Z) (*(0 <=? arg_) && (arg_ <=? 4)*) : Privilege :=
   let l__0 := arg_ in
   if Z.eqb (l__0) (0) then User
   else if Z.eqb (l__0) (1) then VirtualUser
   else if Z.eqb (l__0) (2) then Supervisor
   else if Z.eqb (l__0) (3) then VirtualSupervisor
   else Machine.

Lemma Privilege_num_of_roundtrip (x : Privilege) : Privilege_of_num (num_of_Privilege x) = x.
  destruct x; reflexivity.
Qed.
Lemma num_of_Privilege_injective (x y : Privilege) : num_of_Privilege x = num_of_Privilege y -> x = y.
  intro.
  rewrite <- (Privilege_num_of_roundtrip x).
  rewrite <- (Privilege_num_of_roundtrip y).
  congruence.
Qed.
Definition Privilege_eq_dec (x y : Privilege) : {x = y} + {x <> y}.
  refine (match Z.eq_dec (num_of_Privilege x) (num_of_Privilege y) with
  | left e => left (num_of_Privilege_injective x y e)
  | right ne => right _
  end).
  congruence.
Defined.
Definition Privilege_beq (x y : Privilege) : bool :=
  Z.eqb (num_of_Privilege x) (num_of_Privilege y).
Lemma Privilege_beq_iff x y : Privilege_beq x y = true <-> x = y.
  unfold Privilege_beq.
  rewrite Z.eqb_eq.
  split; [apply num_of_Privilege_injective | congruence].
Qed.
Lemma Privilege_beq_refl x : Privilege_beq x x = true.
apply Privilege_beq_iff; reflexivity.
Qed.
#[export]
Instance Decidable_eq_Privilege : EqDecision Privilege := Privilege_eq_dec.
#[export]
Instance Countable_Privilege : Countable Privilege.
refine {|
  encode x := encode (num_of_Privilege x);
  decode x := z ← decode x; mret (Privilege_of_num z);
|}.
abstract (
  intro s; rewrite decode_encode;
  simpl;
  rewrite Privilege_num_of_roundtrip;
  reflexivity).
Defined.
#[export]
Instance dummy_Privilege : Inhabited Privilege := { inhabitant := User }.


