   | I_S_Timer => 5
   | I_VS_Timer => 6
   | I_M_Timer => 7
   | I_Reserved_8 => 8
   | I_S_External => 9
   | I_VS_External => 10
   | I_M_External => 11
   | I_SG_External => 12
   | I_COF => 13
   | I_Reserved_14 => 14
   | I_Reserved_15 => 15
   end.

Definition InterruptType_of_num (arg_ : Z) (*(0 <=? arg_) && (arg_ <=? 15)*) : InterruptType :=
   let l__0 := arg_ in
   if Z.eqb (l__0) (0) then I_Reserved_0
   else if Z.eqb (l__0) (1) then I_S_Software
   else if Z.eqb (l__0) (2) then I_VS_Software
   else if Z.eqb (l__0) (3) then I_M_Software
   else if Z.eqb (l__0) (4) then I_Reserved_4
   else if Z.eqb (l__0) (5) then I_S_Timer
   else if Z.eqb (l__0) (6) then I_VS_Timer
   else if Z.eqb (l__0) (7) then I_M_Timer
   else if Z.eqb (l__0) (8) then I_Reserved_8
   else if Z.eqb (l__0) (9) then I_S_External
   else if Z.eqb (l__0) (10) then I_VS_External
   else if Z.eqb (l__0) (11) then I_M_External
   else if Z.eqb (l__0) (12) then I_SG_External
   else if Z.eqb (l__0) (13) then I_COF
   else if Z.eqb (l__0) (14) then I_Reserved_14
   else I_Reserved_15.

Lemma InterruptType_num_of_roundtrip (x : InterruptType) : InterruptType_of_num (num_of_InterruptType x) = x.
  destruct x; reflexivity.
Qed.
Lemma num_of_InterruptType_injective (x y : InterruptType) : num_of_InterruptType x = num_of_InterruptType y -> x = y.
  intro.
  rewrite <- (InterruptType_num_of_roundtrip x).
  rewrite <- (InterruptType_num_of_roundtrip y).
  congruence.
Qed.
Definition InterruptType_eq_dec (x y : InterruptType) : {x = y} + {x <> y}.
  refine (match Z.eq_dec (num_of_InterruptType x) (num_of_InterruptType y) with
  | left e => left (num_of_InterruptType_injective x y e)
  | right ne => right _
  end).
  congruence.
Defined.
Definition InterruptType_beq (x y : InterruptType) : bool :=
  Z.eqb (num_of_InterruptType x) (num_of_InterruptType y).
Lemma InterruptType_beq_iff x y : InterruptType_beq x y = true <-> x = y.
  unfold InterruptType_beq.
  rewrite Z.eqb_eq.
  split; [apply num_of_InterruptType_injective | congruence].
Qed.
Lemma InterruptType_beq_refl x : InterruptType_beq x x = true.
apply InterruptType_beq_iff; reflexivity.
Qed.
#[export]
Instance Decidable_eq_InterruptType : EqDecision InterruptType := InterruptType_eq_dec.
#[export]
Instance Countable_InterruptType : Countable InterruptType.
refine {|
  encode x := encode (num_of_InterruptType x);
  decode x := z ← decode x; mret (InterruptType_of_num z);
|}.
abstract (
  intro s; rewrite decode_encode;
  simpl;
  rewrite InterruptType_num_of_roundtrip;
  reflexivity).
Defined.
#[export]
Instance dummy_InterruptType : Inhabited InterruptType := { inhabitant := I_Reserved_0 }.


