| PTW_Implicit_Error : (ExceptionType * gpabits * MemoryAccessType mem_payload) -> PTW_Error
| PTW_Ext_Error : ext_ptw_error -> PTW_Error.
Arguments PTW_Error : clear implicits.

Definition sail_PTW_Error_encode (x : PTW_Error) := match x with
  | PTW_Invalid_Addr x' => encode (0, encode x')
  | PTW_No_Access x' => encode (1, encode x')
  | PTW_Invalid_PTE x' => encode (2, encode x')
  | PTW_No_Permission x' => encode (3, encode x')
  | PTW_Misaligned x' => encode (4, encode x')
  | PTW_PTE_Needs_Update x' => encode (5, encode x')
  | PTW_Implicit_Error x' => encode (6, encode x')
  | PTW_Ext_Error x' => encode (7, encode x') end.
Definition sail_PTW_Error_decode x : option PTW_Error := match decode x with
  | Some (0, x') => PTW_Invalid_Addr <$> decode x'
  | Some (1, x') => PTW_No_Access <$> decode x'
  | Some (2, x') => PTW_Invalid_PTE <$> decode x'
  | Some (3, x') => PTW_No_Permission <$> decode x'
  | Some (4, x') => PTW_Misaligned <$> decode x'
  | Some (5, x') => PTW_PTE_Needs_Update <$> decode x'
  | Some (6, x') => PTW_Implicit_Error <$> decode x'
  | Some (7, x') => PTW_Ext_Error <$> decode x'
  | _ => None end.
Lemma sail_PTW_Error_decode_encode : forall (x : PTW_Error), sail_PTW_Error_decode
  (sail_PTW_Error_encode x)  = Some x.
Proof.
  unfold sail_PTW_Error_decode, sail_PTW_Error_encode;
  intros [x|x|x|x|x|x|x|x]; rewrite !decode_encode; reflexivity.
Qed.

#[export]
Instance Decidable_eq_PTW_Error : EqDecision PTW_Error := decode_encode_eq_dec sail_PTW_Error_encode
  sail_PTW_Error_decode sail_PTW_Error_decode_encode .

#[export]
Instance Countable_PTW_Error : Countable PTW_Error := {|
  encode := sail_PTW_Error_encode;
  decode := sail_PTW_Error_decode;
  decode_encode := sail_PTW_Error_decode_encode
|}.
#[export]
Instance dummy_PTW_Error : Inhabited (PTW_Error) := { inhabitant := PTW_Invalid_Addr inhabitant }.

Inductive TranslationStage := S_Stage | VS_Stage | G_Stage.
Definition num_of_TranslationStage (arg_ : TranslationStage) : Z :=
   match arg_ with | S_Stage => 0 | VS_Stage => 1 | G_Stage => 2 end.

Definition TranslationStage_of_num (arg_ : Z) (*(0 <=? arg_) && (arg_ <=? 2)*) : TranslationStage :=
   let l__0 := arg_ in
   if Z.eqb (l__0) (0) then S_Stage
   else if Z.eqb (l__0) (1) then VS_Stage
   else G_Stage.

Lemma TranslationStage_num_of_roundtrip (x : TranslationStage) : TranslationStage_of_num (num_of_TranslationStage x) = x.
  destruct x; reflexivity.
Qed.
Lemma num_of_TranslationStage_injective (x y : TranslationStage) : num_of_TranslationStage x = num_of_TranslationStage y -> x = y.
  intro.
  rewrite <- (TranslationStage_num_of_roundtrip x).
  rewrite <- (TranslationStage_num_of_roundtrip y).
  congruence.
Qed.
Definition TranslationStage_eq_dec (x y : TranslationStage) : {x = y} + {x <> y}.
  refine (match Z.eq_dec (num_of_TranslationStage x) (num_of_TranslationStage y) with
  | left e => left (num_of_TranslationStage_injective x y e)
  | right ne => right _
  end).
  congruence.
Defined.
Definition TranslationStage_beq (x y : TranslationStage) : bool :=
  Z.eqb (num_of_TranslationStage x) (num_of_TranslationStage y).
Lemma TranslationStage_beq_iff x y : TranslationStage_beq x y = true <-> x = y.
  unfold TranslationStage_beq.
  rewrite Z.eqb_eq.
  split; [apply num_of_TranslationStage_injective | congruence].
Qed.
Lemma TranslationStage_beq_refl x : TranslationStage_beq x x = true.
apply TranslationStage_beq_iff; reflexivity.
Qed.
#[export]
Instance Decidable_eq_TranslationStage : EqDecision TranslationStage := TranslationStage_eq_dec.
#[export]
Instance Countable_TranslationStage : Countable TranslationStage.
refine {|
  encode x := encode (num_of_TranslationStage x);
  decode x := z ← decode x; mret (TranslationStage_of_num z);
|}.
abstract (
  intro s; rewrite decode_encode;
  simpl;
  rewrite TranslationStage_num_of_roundtrip;
  reflexivity).
Defined.
#[export]
Instance dummy_TranslationStage : Inhabited TranslationStage := { inhabitant := S_Stage }.


