refine {|
  encode x := encode (ExceptionContext_trap x, ExceptionContext_excinfo_is_gva x, ExceptionContext_excinfo x, ExceptionContext_excinfo2 x, ExceptionContext_excinst x, ExceptionContext_excinst_offset x, ExceptionContext_ext x);
  decode x := '(x0, x1, x2, x3, x4, x5, x6) ← decode x;
              mret (Build_ExceptionContext x0 x1 x2 x3 x4 x5 x6)
|}.
abstract (
  intros [x0 x1 x2 x3 x4 x5 x6];
  rewrite decode_encode;
  reflexivity).
Defined.

