Definition csrRW : Type := bits 2.

Definition is_sv_mode (v : Z) : bool := member_Z_list v [32; 39; 48; 57].
#[export] Hint Unfold is_sv_mode : sail.

Definition is_svx4_mode (v : Z) : bool := member_Z_list v [34; 41; 50; 59].
#[export] Hint Unfold is_svx4_mode : sail.

Definition is_sv_or_svx4_mode (v : Z) : bool := is_sv_mode v || is_svx4_mode v.
#[export] Hint Unfold is_sv_or_svx4_mode : sail.

Definition is_sv32_mode (v : Z) : bool := (v =? 32) || (v =? 34).
#[export] Hint Unfold is_sv32_mode : sail.

Definition root_level (v : Z) (*is_sv_or_svx4_mode v*) : Z :=
  ((if (v =? 32) || (v =? 34) then 1 else ((if (v =? 39) || (v =? 41) then 2 else ((if (v =? 48) ||
    (v =? 50) then 3 else 4)))))).
#[export] Hint Unfold root_level : sail.

Definition level_range (v : Z) (*is_sv_or_svx4_mode v*) : Type := Z.

Definition vpn_level_size (v : Z) (*is_sv_or_svx4_mode v*) : Z :=
  (12 - (if is_sv32_mode v then 2 else 3)).
#[export] Hint Unfold vpn_level_size : sail.

Definition pte_bits (v : Z) (*is_sv_or_svx4_mode v*) : Type :=
  bits ((if is_sv32_mode v then 32 else 64)).

Definition ppn_bits (v : Z) (*is_sv_or_svx4_mode v*) : Type :=
  bits ((if is_sv32_mode v then 22 else 44)).

Definition vpn_bits (v : Z) (*is_sv_or_svx4_mode v*) : Type := bits (v - 12).

