Inductive access_kind_typ :=
| AK_Write : (write_kind * MemoryAccessType mem_payload) -> access_kind_typ
| AK_Read : (read_kind * MemoryAccessType mem_payload) -> access_kind_typ.
Arguments access_kind_typ : clear implicits.

Definition sail_access_kind_typ_encode (x : access_kind_typ) := match x with
  | AK_Write x' => encode (0, encode x')
  | AK_Read x' => encode (1, encode x') end.
Definition sail_access_kind_typ_decode x : option access_kind_typ := match decode x with
  | Some (0, x') => AK_Write <$> decode x'
  | Some (1, x') => AK_Read <$> decode x'
  | _ => None end.
Lemma sail_access_kind_typ_decode_encode : forall (x : access_kind_typ), sail_access_kind_typ_decode
  (sail_access_kind_typ_encode x)  = Some x.
Proof.
  unfold sail_access_kind_typ_decode, sail_access_kind_typ_encode;
  intros [x|x]; rewrite !decode_encode; reflexivity.
Qed.

#[export]
Instance Decidable_eq_access_kind_typ : EqDecision access_kind_typ := decode_encode_eq_dec
  sail_access_kind_typ_encode sail_access_kind_typ_decode sail_access_kind_typ_decode_encode .

