  encode x := encode (ITrigger_dmode x, ITrigger_hit x, ITrigger_vs x, ITrigger_vu x, ITrigger_nmi x, ITrigger_m x, ITrigger_s x, ITrigger_u x, ITrigger_action x, ITrigger_tdata2 x, ITrigger_tdata3 x, ITrigger_pending x);
  decode x := '(x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11) ← decode x;
              mret (Build_ITrigger x0 x1 x2 x3 x4 x5 x6 x7 x8 x9 x10 x11)
|}.
abstract (
  intros [x0 x1 x2 x3 x4 x5 x6 x7 x8 x9 x10 x11];
  rewrite decode_encode;
  reflexivity).
Defined.

Notation "{[ r 'with' 'ITrigger_dmode' := e ]}" :=
  match r with Build_ITrigger _ (_ as f1) (_ as f2) (_ as f3) (_ as f4) (_ as f5) (_ as f6) (_ as f7) (_ as f8) (_ as f9) (_ as f10) (_ as f11) =>
    Build_ITrigger e f1 f2 f3 f4 f5 f6 f7 f8 f9 f10 f11 end (at level 1).
