Record ETrigger := {
  ETrigger_dmode : bool;
  ETrigger_hit : bool;
  ETrigger_vs : bool;
  ETrigger_vu : bool;
  ETrigger_m : bool;
  ETrigger_s : bool;
  ETrigger_u : bool;
  ETrigger_action : Trig_Action;
  ETrigger_tdata2 : xlenbits;
  ETrigger_tdata3 : xlenbits;
  ETrigger_pending : bool;
}.
Arguments ETrigger : clear implicits.
#[export]
Instance Decidable_eq_ETrigger : EqDecision ETrigger.
   intros [x0 x1 x2 x3 x4 x5 x6 x7 x8 x9 x10].
   intros [y0 y1 y2 y3 y4 y5 y6 y7 y8 y9 y10].
  cmp_record_field x0 y0.
  cmp_record_field x1 y1.
  cmp_record_field x2 y2.
  cmp_record_field x3 y3.
  cmp_record_field x4 y4.
  cmp_record_field x5 y5.
  cmp_record_field x6 y6.
  cmp_record_field x7 y7.
  cmp_record_field x8 y8.
  cmp_record_field x9 y9.
  cmp_record_field x10 y10.
left; subst; reflexivity.
Defined.
#[export]
Instance Countable_ETrigger : Countable ETrigger.
refine {|
  encode x := encode (ETrigger_dmode x, ETrigger_hit x, ETrigger_vs x, ETrigger_vu x, ETrigger_m x, ETrigger_s x, ETrigger_u x, ETrigger_action x, ETrigger_tdata2 x, ETrigger_tdata3 x, ETrigger_pending x);
