Definition IETrigger_bits : Type := mword 64.

Inductive Trigger :=
| T_disabled : TDisabled -> Trigger
| T_icount : ICount -> Trigger
| T_itrigger : ITrigger -> Trigger
| T_etrigger : ETrigger -> Trigger.
Arguments Trigger : clear implicits.

Definition sail_Trigger_encode (x : Trigger) := match x with
  | T_disabled x' => encode (0, encode x')
  | T_icount x' => encode (1, encode x')
  | T_itrigger x' => encode (2, encode x')
  | T_etrigger x' => encode (3, encode x') end.
Definition sail_Trigger_decode x : option Trigger := match decode x with
  | Some (0, x') => T_disabled <$> decode x'
  | Some (1, x') => T_icount <$> decode x'
  | Some (2, x') => T_itrigger <$> decode x'
  | Some (3, x') => T_etrigger <$> decode x'
  | _ => None end.
Lemma sail_Trigger_decode_encode : forall (x : Trigger), sail_Trigger_decode (sail_Trigger_encode x)
   = Some x.
Proof.
  unfold sail_Trigger_decode, sail_Trigger_encode;
  intros [x|x|x|x]; rewrite !decode_encode; reflexivity.
Qed.

#[export]
Instance Decidable_eq_Trigger : EqDecision Trigger := decode_encode_eq_dec sail_Trigger_encode
  sail_Trigger_decode sail_Trigger_decode_encode .

#[export]
Instance Countable_Trigger : Countable Trigger := {|
  encode := sail_Trigger_encode;
  decode := sail_Trigger_decode;
  decode_encode := sail_Trigger_decode_encode
|}.
#[export]
Instance dummy_Trigger : Inhabited (Trigger) := { inhabitant := T_disabled inhabitant }.

Definition TInfo : Type := mword 64.

Definition TData1 : Type := mword 64.

Definition TControl : Type := mword 64.

Definition SContext : Type := mword 64.

Definition MContext : Type := mword 64.

Definition External_Trigger : Type := mword 64.

Definition Trigger_Extra_RV32 : Type := mword 32.

Definition Trigger_Extra_RV64 : Type := mword 64.

Inductive tdata := TDATA1 | TDATA2 | TDATA3.
Definition num_of_tdata (arg_ : tdata) : Z :=
   match arg_ with | TDATA1 => 0 | TDATA2 => 1 | TDATA3 => 2 end.

Definition tdata_of_num (arg_ : Z) (*(0 <=? arg_) && (arg_ <=? 2)*) : tdata :=
   let l__0 := arg_ in
   if Z.eqb (l__0) (0) then TDATA1
   else if Z.eqb (l__0) (1) then TDATA2
   else TDATA3.

Lemma tdata_num_of_roundtrip (x : tdata) : tdata_of_num (num_of_tdata x) = x.
  destruct x; reflexivity.
Qed.
Lemma num_of_tdata_injective (x y : tdata) : num_of_tdata x = num_of_tdata y -> x = y.
  intro.
  rewrite <- (tdata_num_of_roundtrip x).
  rewrite <- (tdata_num_of_roundtrip y).
  congruence.
Qed.
Definition tdata_eq_dec (x y : tdata) : {x = y} + {x <> y}.
  refine (match Z.eq_dec (num_of_tdata x) (num_of_tdata y) with
  | left e => left (num_of_tdata_injective x y e)
  | right ne => right _
  end).
  congruence.
Defined.
Definition tdata_beq (x y : tdata) : bool :=
  Z.eqb (num_of_tdata x) (num_of_tdata y).
Lemma tdata_beq_iff x y : tdata_beq x y = true <-> x = y.
  unfold tdata_beq.
  rewrite Z.eqb_eq.
  split; [apply num_of_tdata_injective | congruence].
Qed.
Lemma tdata_beq_refl x : tdata_beq x x = true.
apply tdata_beq_iff; reflexivity.
Qed.
#[export]
Instance Decidable_eq_tdata : EqDecision tdata := tdata_eq_dec.
#[export]
Instance Countable_tdata : Countable tdata.
refine {|
  encode x := encode (num_of_tdata x);
  decode x := z ← decode x; mret (tdata_of_num z);
|}.
abstract (
  intro s; rewrite decode_encode;
  simpl;
  rewrite tdata_num_of_roundtrip;
  reflexivity).
Defined.
#[export]
Instance dummy_tdata : Inhabited tdata := { inhabitant := TDATA1 }.


