Definition valid_misaligned_order (n : Z) (first : Z) (last : Z) (step : Z) : bool :=
  (first =? 0) && ((last =? (n - 1)) && (step =? 1)) ||
    (first =? (n - 1)) && ((last =? 0) && (step =? ((- 1)))).
#[export] Hint Unfold valid_misaligned_order : sail.

Record Phys_Mem_Access_Info := {
  Phys_Mem_Access_Info_splittable : Splittability;
  Phys_Mem_Access_Info_granule_size_exp : mag_size_exp;
}.
Arguments Phys_Mem_Access_Info : clear implicits.
#[export]
Instance Decidable_eq_Phys_Mem_Access_Info : EqDecision Phys_Mem_Access_Info.
   intros [x0 x1].
   intros [y0 y1].
  cmp_record_field x0 y0.
  cmp_record_field x1 y1.
left; subst; reflexivity.
Defined.
#[export]
Instance Countable_Phys_Mem_Access_Info : Countable Phys_Mem_Access_Info.
refine {|
  encode x := encode (Phys_Mem_Access_Info_splittable x, Phys_Mem_Access_Info_granule_size_exp x);
  decode x := '(x0, x1) ← decode x;
              mret (Build_Phys_Mem_Access_Info x0 x1)
|}.
abstract (
  intros [x0 x1];
  rewrite decode_encode;
  reflexivity).
Defined.

Notation "{[ r 'with' 'Phys_Mem_Access_Info_splittable' := e ]}" :=
  match r with Build_Phys_Mem_Access_Info _ (_ as f1) =>
    Build_Phys_Mem_Access_Info e f1 end (at level 1).
Notation "{[ r 'with' 'Phys_Mem_Access_Info_granule_size_exp' := e ]}" :=
  match r with Build_Phys_Mem_Access_Info (_ as f0) _ =>
    Build_Phys_Mem_Access_Info f0 e end (at level 1).
#[export]
Instance dummy_Phys_Mem_Access_Info : Inhabited (Phys_Mem_Access_Info) := {
  inhabitant := {|
    Phys_Mem_Access_Info_splittable := inhabitant;
    Phys_Mem_Access_Info_granule_size_exp := inhabitant
|} }.


Definition pte_flags_bits : Type := bits 8.

Definition pte_ext_bits : Type := bits 10.

Definition PTE_Ext : Type := mword 10.

Definition PTE_Flags : Type := mword 8.

Inductive pte_check_failure :=
| PTE_No_Permission : unit -> pte_check_failure
| PTE_No_Access : unit -> pte_check_failure
| PTE_Ext_Failure : ext_ptw_fail -> pte_check_failure.
Arguments pte_check_failure : clear implicits.

Definition sail_pte_check_failure_encode (x : pte_check_failure) := match x with
  | PTE_No_Permission x' => encode (0, encode x')
  | PTE_No_Access x' => encode (1, encode x')
  | PTE_Ext_Failure x' => encode (2, encode x') end.
Definition sail_pte_check_failure_decode x : option pte_check_failure := match decode x with
  | Some (0, x') => PTE_No_Permission <$> decode x'
  | Some (1, x') => PTE_No_Access <$> decode x'
  | Some (2, x') => PTE_Ext_Failure <$> decode x'
  | _ => None end.
Lemma sail_pte_check_failure_decode_encode : forall (x : pte_check_failure),
  sail_pte_check_failure_decode (sail_pte_check_failure_encode x)  = Some x.
Proof.
  unfold sail_pte_check_failure_decode, sail_pte_check_failure_encode;
  intros [x|x|x]; rewrite !decode_encode; reflexivity.
Qed.

#[export]
Instance Decidable_eq_pte_check_failure : EqDecision pte_check_failure := decode_encode_eq_dec
  sail_pte_check_failure_encode sail_pte_check_failure_decode sail_pte_check_failure_decode_encode .

#[export]
Instance Countable_pte_check_failure : Countable pte_check_failure := {|
  encode := sail_pte_check_failure_encode;
  decode := sail_pte_check_failure_decode;
  decode_encode := sail_pte_check_failure_decode_encode
|}.
#[export]
Instance dummy_pte_check_failure : Inhabited (pte_check_failure) := {
  inhabitant := PTE_No_Permission inhabitant
}.

Inductive PTE_Check :=
| PTE_Check_Success : ext_ptw -> PTE_Check
| PTE_Check_Failure : (ext_ptw * pte_check_failure) -> PTE_Check.
Arguments PTE_Check : clear implicits.

Definition sail_PTE_Check_encode (x : PTE_Check) := match x with
  | PTE_Check_Success x' => encode (0, encode x')
  | PTE_Check_Failure x' => encode (1, encode x') end.
Definition sail_PTE_Check_decode x : option PTE_Check := match decode x with
  | Some (0, x') => PTE_Check_Success <$> decode x'
  | Some (1, x') => PTE_Check_Failure <$> decode x'
  | _ => None end.
Lemma sail_PTE_Check_decode_encode : forall (x : PTE_Check), sail_PTE_Check_decode
  (sail_PTE_Check_encode x)  = Some x.
Proof.
  unfold sail_PTE_Check_decode, sail_PTE_Check_encode;
  intros [x|x]; rewrite !decode_encode; reflexivity.
Qed.

#[export]
Instance Decidable_eq_PTE_Check : EqDecision PTE_Check := decode_encode_eq_dec sail_PTE_Check_encode
  sail_PTE_Check_decode sail_PTE_Check_decode_encode .

#[export]
Instance Countable_PTE_Check : Countable PTE_Check := {|
  encode := sail_PTE_Check_encode;
  decode := sail_PTE_Check_decode;
  decode_encode := sail_PTE_Check_decode_encode
|}.
#[export]
Instance dummy_PTE_Check : Inhabited (PTE_Check) := { inhabitant := PTE_Check_Success inhabitant }.

