Definition PTW_Result (v : Z) (*is_sv_or_svx4_mode v*) : Type :=
  result ((PTW_Output v * ext_ptw)) ((PTW_Error * ext_ptw)).

Definition TR_Result (paddr : Type) (failure : Type) : Type :=
  result ((paddr * page_based_mem_type * ext_ptw)) ((failure * ext_ptw)).

Inductive ExecutionResult :=
| Retire_Success : unit -> ExecutionResult
| ExecuteAs : instruction -> ExecutionResult
| Enter_Wait : WaitReason -> ExecutionResult
| Illegal_Instruction : unit -> ExecutionResult
| Virtual_Instruction : unit -> ExecutionResult
| Trap : (Privilege * ExceptionContext * xlenbits) -> ExecutionResult
| Ext_CSR_Check_Failure : unit -> ExecutionResult
| Ext_ControlAddr_Check_Failure : ext_control_addr_error -> ExecutionResult
| Ext_DataAddr_Check_Failure : ext_data_addr_error -> ExecutionResult
| Ext_XRET_Priv_Failure : unit -> ExecutionResult.
Arguments ExecutionResult : clear implicits.

Definition sail_ExecutionResult_encode (x : ExecutionResult) := match x with
  | Retire_Success x' => encode (0, encode x')
  | ExecuteAs x' => encode (1, encode x')
  | Enter_Wait x' => encode (2, encode x')
  | Illegal_Instruction x' => encode (3, encode x')
  | Virtual_Instruction x' => encode (4, encode x')
  | Trap x' => encode (5, encode x')
  | Ext_CSR_Check_Failure x' => encode (6, encode x')
  | Ext_ControlAddr_Check_Failure x' => encode (7, encode x')
  | Ext_DataAddr_Check_Failure x' => encode (8, encode x')
  | Ext_XRET_Priv_Failure x' => encode (9, encode x') end.
Definition sail_ExecutionResult_decode x : option ExecutionResult := match decode x with
  | Some (0, x') => Retire_Success <$> decode x'
  | Some (1, x') => ExecuteAs <$> decode x'
  | Some (2, x') => Enter_Wait <$> decode x'
  | Some (3, x') => Illegal_Instruction <$> decode x'
  | Some (4, x') => Virtual_Instruction <$> decode x'
  | Some (5, x') => Trap <$> decode x'
  | Some (6, x') => Ext_CSR_Check_Failure <$> decode x'
  | Some (7, x') => Ext_ControlAddr_Check_Failure <$> decode x'
  | Some (8, x') => Ext_DataAddr_Check_Failure <$> decode x'
  | Some (9, x') => Ext_XRET_Priv_Failure <$> decode x'
  | _ => None end.
Lemma sail_ExecutionResult_decode_encode : forall (x : ExecutionResult), sail_ExecutionResult_decode
  (sail_ExecutionResult_encode x)  = Some x.
Proof.
  unfold sail_ExecutionResult_decode, sail_ExecutionResult_encode;
  intros [x|x|x|x|x|x|x|x|x|x]; rewrite !decode_encode; reflexivity.
Qed.

#[export]
Instance Decidable_eq_ExecutionResult : EqDecision ExecutionResult := decode_encode_eq_dec
  sail_ExecutionResult_encode sail_ExecutionResult_decode sail_ExecutionResult_decode_encode .

#[export]
Instance Countable_ExecutionResult : Countable ExecutionResult := {|
  encode := sail_ExecutionResult_encode;
  decode := sail_ExecutionResult_decode;
  decode_encode := sail_ExecutionResult_decode_encode
|}.
#[export]
Instance dummy_ExecutionResult : Inhabited (ExecutionResult) := {
  inhabitant := Retire_Success inhabitant
}.

