Inductive seed_opst := BIST | ES16 | WAIT | DEAD.
Definition num_of_seed_opst (arg_ : seed_opst) : Z :=
   match arg_ with | BIST => 0 | ES16 => 1 | WAIT => 2 | DEAD => 3 end.

Definition seed_opst_of_num (arg_ : Z) (*(0 <=? arg_) && (arg_ <=? 3)*) : seed_opst :=
   let l__0 := arg_ in
   if Z.eqb (l__0) (0) then BIST
   else if Z.eqb (l__0) (1) then ES16
   else if Z.eqb (l__0) (2) then WAIT
   else DEAD.

Lemma seed_opst_num_of_roundtrip (x : seed_opst) : seed_opst_of_num (num_of_seed_opst x) = x.
  destruct x; reflexivity.
Qed.
Lemma num_of_seed_opst_injective (x y : seed_opst) : num_of_seed_opst x = num_of_seed_opst y -> x = y.
  intro.
  rewrite <- (seed_opst_num_of_roundtrip x).
  rewrite <- (seed_opst_num_of_roundtrip y).
  congruence.
Qed.
Definition seed_opst_eq_dec (x y : seed_opst) : {x = y} + {x <> y}.
  refine (match Z.eq_dec (num_of_seed_opst x) (num_of_seed_opst y) with
  | left e => left (num_of_seed_opst_injective x y e)
  | right ne => right _
  end).
  congruence.
Defined.
Definition seed_opst_beq (x y : seed_opst) : bool :=
  Z.eqb (num_of_seed_opst x) (num_of_seed_opst y).
Lemma seed_opst_beq_iff x y : seed_opst_beq x y = true <-> x = y.
  unfold seed_opst_beq.
  rewrite Z.eqb_eq.
  split; [apply num_of_seed_opst_injective | congruence].
Qed.
Lemma seed_opst_beq_refl x : seed_opst_beq x x = true.
apply seed_opst_beq_iff; reflexivity.
Qed.
#[export]
Instance Decidable_eq_seed_opst : EqDecision seed_opst := seed_opst_eq_dec.
#[export]
Instance Countable_seed_opst : Countable seed_opst.
refine {|
  encode x := encode (num_of_seed_opst x);
  decode x := z ← decode x; mret (seed_opst_of_num z);
|}.
abstract (
  intro s; rewrite decode_encode;
  simpl;
  rewrite seed_opst_num_of_roundtrip;
  reflexivity).
Defined.
#[export]
Instance dummy_seed_opst : Inhabited seed_opst := { inhabitant := BIST }.


Definition Srmcfg : Type := mword 64.

Inductive cbie := CBIE_ILLEGAL | CBIE_EXEC_FLUSH | CBIE_EXEC_INVAL.
Definition num_of_cbie (arg_ : cbie) : Z :=
   match arg_ with | CBIE_ILLEGAL => 0 | CBIE_EXEC_FLUSH => 1 | CBIE_EXEC_INVAL => 2 end.

Definition cbie_of_num (arg_ : Z) (*(0 <=? arg_) && (arg_ <=? 2)*) : cbie :=
   let l__0 := arg_ in
   if Z.eqb (l__0) (0) then CBIE_ILLEGAL
   else if Z.eqb (l__0) (1) then CBIE_EXEC_FLUSH
   else CBIE_EXEC_INVAL.

Lemma cbie_num_of_roundtrip (x : cbie) : cbie_of_num (num_of_cbie x) = x.
  destruct x; reflexivity.
Qed.
Lemma num_of_cbie_injective (x y : cbie) : num_of_cbie x = num_of_cbie y -> x = y.
  intro.
  rewrite <- (cbie_num_of_roundtrip x).
  rewrite <- (cbie_num_of_roundtrip y).
  congruence.
Qed.
Definition cbie_eq_dec (x y : cbie) : {x = y} + {x <> y}.
  refine (match Z.eq_dec (num_of_cbie x) (num_of_cbie y) with
  | left e => left (num_of_cbie_injective x y e)
  | right ne => right _
  end).
  congruence.
Defined.
Definition cbie_beq (x y : cbie) : bool :=
  Z.eqb (num_of_cbie x) (num_of_cbie y).
Lemma cbie_beq_iff x y : cbie_beq x y = true <-> x = y.
  unfold cbie_beq.
  rewrite Z.eqb_eq.
  split; [apply num_of_cbie_injective | congruence].
Qed.
Lemma cbie_beq_refl x : cbie_beq x x = true.
apply cbie_beq_iff; reflexivity.
Qed.
#[export]
Instance Decidable_eq_cbie : EqDecision cbie := cbie_eq_dec.
#[export]
Instance Countable_cbie : Countable cbie.
refine {|
  encode x := encode (num_of_cbie x);
  decode x := z ← decode x; mret (cbie_of_num z);
|}.
abstract (
  intro s; rewrite decode_encode;
  simpl;
  rewrite cbie_num_of_roundtrip;
  reflexivity).
Defined.
#[export]
Instance dummy_cbie : Inhabited cbie := { inhabitant := CBIE_ILLEGAL }.


Inductive checked_cbop := CBOP_ILLEGAL | CBOP_ILLEGAL_VIRTUAL | CBOP_INVAL_FLUSH | CBOP_INVAL_INVAL.
Definition num_of_checked_cbop (arg_ : checked_cbop) : Z :=
   match arg_ with
   | CBOP_ILLEGAL => 0
   | CBOP_ILLEGAL_VIRTUAL => 1
   | CBOP_INVAL_FLUSH => 2
   | CBOP_INVAL_INVAL => 3
   end.

Definition checked_cbop_of_num (arg_ : Z) (*(0 <=? arg_) && (arg_ <=? 3)*) : checked_cbop :=
   let l__0 := arg_ in
   if Z.eqb (l__0) (0) then CBOP_ILLEGAL
   else if Z.eqb (l__0) (1) then CBOP_ILLEGAL_VIRTUAL
   else if Z.eqb (l__0) (2) then CBOP_INVAL_FLUSH
   else CBOP_INVAL_INVAL.

Lemma checked_cbop_num_of_roundtrip (x : checked_cbop) : checked_cbop_of_num (num_of_checked_cbop x) = x.
  destruct x; reflexivity.
Qed.
Lemma num_of_checked_cbop_injective (x y : checked_cbop) : num_of_checked_cbop x = num_of_checked_cbop y -> x = y.
  intro.
  rewrite <- (checked_cbop_num_of_roundtrip x).
  rewrite <- (checked_cbop_num_of_roundtrip y).
  congruence.
Qed.
Definition checked_cbop_eq_dec (x y : checked_cbop) : {x = y} + {x <> y}.
  refine (match Z.eq_dec (num_of_checked_cbop x) (num_of_checked_cbop y) with
  | left e => left (num_of_checked_cbop_injective x y e)
  | right ne => right _
  end).
  congruence.
Defined.
Definition checked_cbop_beq (x y : checked_cbop) : bool :=
  Z.eqb (num_of_checked_cbop x) (num_of_checked_cbop y).
Lemma checked_cbop_beq_iff x y : checked_cbop_beq x y = true <-> x = y.
  unfold checked_cbop_beq.
  rewrite Z.eqb_eq.
  split; [apply num_of_checked_cbop_injective | congruence].
Qed.
Lemma checked_cbop_beq_refl x : checked_cbop_beq x x = true.
apply checked_cbop_beq_iff; reflexivity.
Qed.
#[export]
Instance Decidable_eq_checked_cbop : EqDecision checked_cbop := checked_cbop_eq_dec.
#[export]
Instance Countable_checked_cbop : Countable checked_cbop.
refine {|
  encode x := encode (num_of_checked_cbop x);
  decode x := z ← decode x; mret (checked_cbop_of_num z);
|}.
abstract (
  intro s; rewrite decode_encode;
  simpl;
  rewrite checked_cbop_num_of_roundtrip;
  reflexivity).
Defined.
#[export]
Instance dummy_checked_cbop : Inhabited checked_cbop := { inhabitant := CBOP_ILLEGAL }.


Record instr_info := {
  instr_info_fetch_privilege : Privilege;
  instr_info_fetch_trigger_reentrance : bool;
  instr_info_fetched_instruction : instruction;
  instr_info_executed_instruction : option instruction;
  instr_info_instbits : instbits_typ;
  instr_info_compressed : bool;
}.
Arguments instr_info : clear implicits.
#[export]
Instance Decidable_eq_instr_info : EqDecision instr_info.
   intros [x0 x1 x2 x3 x4 x5].
   intros [y0 y1 y2 y3 y4 y5].
  cmp_record_field x0 y0.
  cmp_record_field x1 y1.
  cmp_record_field x2 y2.
  cmp_record_field x3 y3.
  cmp_record_field x4 y4.
  cmp_record_field x5 y5.
left; subst; reflexivity.
Defined.
#[export]
Instance Countable_instr_info : Countable instr_info.
refine {|
  encode x := encode (instr_info_fetch_privilege x, instr_info_fetch_trigger_reentrance x, instr_info_fetched_instruction x, instr_info_executed_instruction x, instr_info_instbits x, instr_info_compressed x);
  decode x := '(x0, x1, x2, x3, x4, x5) ← decode x;
              mret (Build_instr_info x0 x1 x2 x3 x4 x5)
|}.
abstract (
  intros [x0 x1 x2 x3 x4 x5];
  rewrite decode_encode;
  reflexivity).
Defined.

Notation "{[ r 'with' 'instr_info_fetch_privilege' := e ]}" :=
  match r with Build_instr_info _ (_ as f1) (_ as f2) (_ as f3) (_ as f4) (_ as f5) =>
    Build_instr_info e f1 f2 f3 f4 f5 end (at level 1).
Notation "{[ r 'with' 'instr_info_fetch_trigger_reentrance' := e ]}" :=
  match r with Build_instr_info (_ as f0) _ (_ as f2) (_ as f3) (_ as f4) (_ as f5) =>
    Build_instr_info f0 e f2 f3 f4 f5 end (at level 1).
Notation "{[ r 'with' 'instr_info_fetched_instruction' := e ]}" :=
  match r with Build_instr_info (_ as f0) (_ as f1) _ (_ as f3) (_ as f4) (_ as f5) =>
    Build_instr_info f0 f1 e f3 f4 f5 end (at level 1).
Notation "{[ r 'with' 'instr_info_executed_instruction' := e ]}" :=
  match r with Build_instr_info (_ as f0) (_ as f1) (_ as f2) _ (_ as f4) (_ as f5) =>
    Build_instr_info f0 f1 f2 e f4 f5 end (at level 1).
Notation "{[ r 'with' 'instr_info_instbits' := e ]}" :=
  match r with Build_instr_info (_ as f0) (_ as f1) (_ as f2) (_ as f3) _ (_ as f5) =>
    Build_instr_info f0 f1 f2 f3 e f5 end (at level 1).
Notation "{[ r 'with' 'instr_info_compressed' := e ]}" :=
  match r with Build_instr_info (_ as f0) (_ as f1) (_ as f2) (_ as f3) (_ as f4) _ =>
    Build_instr_info f0 f1 f2 f3 f4 e end (at level 1).
#[export]
Instance dummy_instr_info : Inhabited (instr_info) := {
  inhabitant := {|
    instr_info_fetch_privilege := inhabitant;
    instr_info_fetch_trigger_reentrance := inhabitant;
    instr_info_fetched_instruction := inhabitant;
    instr_info_executed_instruction := inhabitant;
    instr_info_instbits := inhabitant;
    instr_info_compressed := inhabitant
|} }.


Inductive HartState :=
| HART_ACTIVE : unit -> HartState
| HART_WAITING : (WaitReason * instr_info) -> HartState.
Arguments HartState : clear implicits.

Definition sail_HartState_encode (x : HartState) := match x with
  | HART_ACTIVE x' => encode (0, encode x')
  | HART_WAITING x' => encode (1, encode x') end.
Definition sail_HartState_decode x : option HartState := match decode x with
  | Some (0, x') => HART_ACTIVE <$> decode x'
  | Some (1, x') => HART_WAITING <$> decode x'
  | _ => None end.
Lemma sail_HartState_decode_encode : forall (x : HartState), sail_HartState_decode
  (sail_HartState_encode x)  = Some x.
Proof.
  unfold sail_HartState_decode, sail_HartState_encode;
  intros [x|x]; rewrite !decode_encode; reflexivity.
Qed.

#[export]
Instance Decidable_eq_HartState : EqDecision HartState := decode_encode_eq_dec sail_HartState_encode
  sail_HartState_decode sail_HartState_decode_encode .

#[export]
Instance Countable_HartState : Countable HartState := {|
  encode := sail_HartState_encode;
  decode := sail_HartState_decode;
  decode_encode := sail_HartState_decode_encode
|}.
#[export]
Instance dummy_HartState : Inhabited (HartState) := { inhabitant := HART_ACTIVE inhabitant }.

