Inductive Step :=
| Step_Pending_Interrupt : (InterruptType * Privilege) -> Step
| Step_Pending_Trigger : (Trig_Action * trigger_index * xlenbits) -> Step
| Step_Ext_Fetch_Failure : ext_fetch_addr_error -> Step
| Step_Fetch_Failure : ExceptionContext -> Step
| Step_Execute : (ExecutionResult * instr_info) -> Step
| Step_Waiting : WaitReason -> Step.
Arguments Step : clear implicits.

Definition sail_Step_encode (x : Step) := match x with
  | Step_Pending_Interrupt x' => encode (0, encode x')
  | Step_Pending_Trigger x' => encode (1, encode x')
  | Step_Ext_Fetch_Failure x' => encode (2, encode x')
  | Step_Fetch_Failure x' => encode (3, encode x')
  | Step_Execute x' => encode (4, encode x')
  | Step_Waiting x' => encode (5, encode x') end.
Definition sail_Step_decode x : option Step := match decode x with
  | Some (0, x') => Step_Pending_Interrupt <$> decode x'
  | Some (1, x') => Step_Pending_Trigger <$> decode x'
  | Some (2, x') => Step_Ext_Fetch_Failure <$> decode x'
  | Some (3, x') => Step_Fetch_Failure <$> decode x'
  | Some (4, x') => Step_Execute <$> decode x'
  | Some (5, x') => Step_Waiting <$> decode x'
  | _ => None end.
Lemma sail_Step_decode_encode : forall (x : Step), sail_Step_decode (sail_Step_encode x)  = Some x.
Proof.
  unfold sail_Step_decode, sail_Step_encode;
  intros [x|x|x|x|x|x]; rewrite !decode_encode; reflexivity.
Qed.

#[export]
Instance Decidable_eq_Step : EqDecision Step := decode_encode_eq_dec sail_Step_encode
  sail_Step_decode sail_Step_decode_encode .

#[export]
Instance Countable_Step : Countable Step := {|
  encode := sail_Step_encode;
  decode := sail_Step_decode;
  decode_encode := sail_Step_decode_encode
|}.
#[export]
Instance dummy_Step : Inhabited (Step) := { inhabitant := Step_Pending_Interrupt inhabitant }.

