Inductive ISA_Format := Canonical_Lowercase | DeviceTree_ISA_Extensions.
Definition num_of_ISA_Format (arg_ : ISA_Format) : Z :=
   match arg_ with | Canonical_Lowercase => 0 | DeviceTree_ISA_Extensions => 1 end.

Definition ISA_Format_of_num (arg_ : Z) (*(0 <=? arg_) && (arg_ <=? 1)*) : ISA_Format :=
   let l__0 := arg_ in
   if Z.eqb (l__0) (0) then Canonical_Lowercase
   else DeviceTree_ISA_Extensions.

Lemma ISA_Format_num_of_roundtrip (x : ISA_Format) : ISA_Format_of_num (num_of_ISA_Format x) = x.
  destruct x; reflexivity.
Qed.
Lemma num_of_ISA_Format_injective (x y : ISA_Format) : num_of_ISA_Format x = num_of_ISA_Format y -> x = y.
  intro.
  rewrite <- (ISA_Format_num_of_roundtrip x).
  rewrite <- (ISA_Format_num_of_roundtrip y).
  congruence.
Qed.
Definition ISA_Format_eq_dec (x y : ISA_Format) : {x = y} + {x <> y}.
  refine (match Z.eq_dec (num_of_ISA_Format x) (num_of_ISA_Format y) with
  | left e => left (num_of_ISA_Format_injective x y e)
  | right ne => right _
  end).
  congruence.
Defined.
Definition ISA_Format_beq (x y : ISA_Format) : bool :=
  Z.eqb (num_of_ISA_Format x) (num_of_ISA_Format y).
Lemma ISA_Format_beq_iff x y : ISA_Format_beq x y = true <-> x = y.
  unfold ISA_Format_beq.
  rewrite Z.eqb_eq.
  split; [apply num_of_ISA_Format_injective | congruence].
Qed.
Lemma ISA_Format_beq_refl x : ISA_Format_beq x x = true.
apply ISA_Format_beq_iff; reflexivity.
Qed.
#[export]
Instance Decidable_eq_ISA_Format : EqDecision ISA_Format := ISA_Format_eq_dec.
#[export]
Instance Countable_ISA_Format : Countable ISA_Format.
refine {|
  encode x := encode (num_of_ISA_Format x);
  decode x := z ← decode x; mret (ISA_Format_of_num z);
|}.
abstract (
  intro s; rewrite decode_encode;
  simpl;
  rewrite ISA_Format_num_of_roundtrip;
  reflexivity).
Defined.
#[export]
Instance dummy_ISA_Format : Inhabited ISA_Format := { inhabitant := Canonical_Lowercase }.


Definition not (b : bool) : bool := negb (b).

Definition is_implicit_access (access : MemoryAccessType mem_payload) : bool :=
   match access with
   | InstructionFetch tt => true
   | Load PageTableEntry => true
   | Store PageTableEntry => true
   | _ => false
   end.

Definition ak_memory_access (acc : access_kind_typ) : MemoryAccessType mem_payload :=
   match acc with | AK_Write (_, access) => access | AK_Read (_, access) => access end.

Definition ak_is_explicit (acc : access_kind_typ) : bool :=
   not ((is_implicit_access ((ak_memory_access (acc))))).

Definition ak_is_ifetch (acc : access_kind_typ) : bool :=
   generic_eq ((ak_memory_access (acc))) ((InstructionFetch (tt))).

Definition ak_is_ttw (acc : access_kind_typ) : bool :=
   match ak_memory_access (acc) with
   | Load PageTableEntry => true
   | Store PageTableEntry => true
   | _ => false
   end.

Definition ak_is_relaxed (acc : access_kind_typ) : bool :=
   andb ((ak_is_explicit (acc)))
     ((match acc with
     | AK_Write (Write_plain, _) => true
     | AK_Write (Write_RISCV_conditional, _) => true
     | AK_Read (Read_plain, _) => true
     | AK_Read (Read_RISCV_reserved, _) => true
     | _ => false
     end
      : bool)).

Definition ak_is_rel_acq_rcsc (acc : access_kind_typ) : bool :=
   andb ((ak_is_explicit (acc)))
     ((match acc with
     | AK_Write (Write_RISCV_strong_release, _) => true
     | AK_Write (Write_RISCV_conditional_strong_release, _) => true
     | AK_Read (Read_RISCV_strong_acquire, _) => true
     | AK_Read (Read_RISCV_reserved_strong_acquire, _) => true
     | _ => false
     end
      : bool)).

Definition ak_is_rel_acq_rcpc (acc : access_kind_typ) : bool :=
   andb ((ak_is_explicit (acc)))
     ((match acc with
     | AK_Write (Write_RISCV_release, _) => true
     | AK_Write (Write_RISCV_conditional_release, _) => true
     | AK_Read (Read_RISCV_acquire, _) => true
     | AK_Read (Read_RISCV_reserved_acquire, _) => true
     | _ => false
     end
      : bool)).

Definition ak_is_standalone (acc : access_kind_typ) : bool :=
   andb ((ak_is_explicit (acc)))
     ((match ak_memory_access (acc) with
     | LoadReserved _ => false
     | StoreConditional _ => false
     | Atomic _ => false
     | _ => true
     end
      : bool)).

Definition ak_is_exclusive (acc : access_kind_typ) : bool :=
   match ak_memory_access (acc) with
   | LoadReserved _ => true
   | StoreConditional _ => true
   | _ => false
   end.

Definition ak_is_atomic_rmw (acc : access_kind_typ) : bool :=
   match ak_memory_access (acc) with | Atomic _ => true | _ => false end.





