Variant register : Type :=
  | R_HartState :> register_HartState -> register
  | R_Privilege :> register_Privilege -> register
  | R_bitvector_1 :> register_bitvector_1 -> register
  | R_bitvector_128 :> register_bitvector_128 -> register
  | R_bitvector_192 :> register_bitvector_192 -> register
  | R_bitvector_3 :> register_bitvector_3 -> register
  | R_bitvector_32 :> register_bitvector_32 -> register
  | R_bitvector_320 :> register_bitvector_320 -> register
  | R_bitvector_4 :> register_bitvector_4 -> register
  | R_bitvector_5 :> register_bitvector_5 -> register
  | R_bitvector_64 :> register_bitvector_64 -> register
  | R_bitvector_704 :> register_bitvector_704 -> register
  | R_bitvector_exp_8 :> register_bitvector_exp_8 -> register
  | R_bool :> register_bool -> register
  | R_list_PMA_Region :> register_list_PMA_Region -> register
  | R_option_bitvector_64 :> register_option_bitvector_64 -> register
  | R_option_tuple__range_0_15_tdata :> register_option_tuple__range_0_15_tdata -> register
  | R_option_tuple__range_3_31_event_csr :> register_option_tuple__range_3_31_event_csr -> register
  | R_vector_16_Trigger :> register_vector_16_Trigger -> register
  | R_vector_32_bitvector_64 :> register_vector_32_bitvector_64 -> register
  | R_vector_64_bitvector_64 :> register_vector_64_bitvector_64 -> register
  | R_vector_64_bitvector_8 :> register_vector_64_bitvector_8 -> register
  | R_vector_64_option_TLB_Entry :> register_vector_64_option_TLB_Entry -> register
.

Definition type_of_register (r : register) : Type :=
  match r with
  | R_HartState _ => HartState
  | R_Privilege _ => Privilege
  | R_bitvector_1 _ => ((mword 1))
  | R_bitvector_128 _ => ((mword 128))
  | R_bitvector_192 _ => ((mword 192))
  | R_bitvector_3 _ => ((mword 3))
  | R_bitvector_32 _ => ((mword 32))
  | R_bitvector_320 _ => ((mword 320))
  | R_bitvector_4 _ => ((mword 4))
  | R_bitvector_5 _ => ((mword 5))
  | R_bitvector_64 _ => ((mword 64))
  | R_bitvector_704 _ => ((mword 704))
  | R_bitvector_exp_8 _ => ((mword (2 ^ 8)))
  | R_bool _ => bool
  | R_list_PMA_Region _ => ((list PMA_Region))
  | R_option_bitvector_64 _ => ((option (mword ((if 64 =? 32 then 34 else 64)))))
  | R_option_tuple__range_0_15_tdata _ => ((option ((Z * tdata))))
  | R_option_tuple__range_3_31_event_csr _ => ((option ((Z * event_csr))))
  | R_vector_16_Trigger _ => ((vec Trigger 16))
  | R_vector_32_bitvector_64 _ => ((vec (mword 64) 32))
  | R_vector_64_bitvector_64 _ => ((vec (mword 64) 64))
  | R_vector_64_bitvector_8 _ => ((vec (mword 8) 64))
  | R_vector_64_option_TLB_Entry _ => ((vec (option TLB_Entry) (2 ^ 6)))
  end.

  Definition register_encode (r : register) : positive :=
    match r with
    | R_HartState r => encode (0, encode r)
    | R_Privilege r => encode (1, encode r)
    | R_bitvector_1 r => encode (2, encode r)
    | R_bitvector_128 r => encode (3, encode r)
    | R_bitvector_192 r => encode (4, encode r)
    | R_bitvector_3 r => encode (5, encode r)
    | R_bitvector_32 r => encode (6, encode r)
    | R_bitvector_320 r => encode (7, encode r)
    | R_bitvector_4 r => encode (8, encode r)
    | R_bitvector_5 r => encode (9, encode r)
    | R_bitvector_64 r => encode (10, encode r)
    | R_bitvector_704 r => encode (11, encode r)
    | R_bitvector_exp_8 r => encode (12, encode r)
    | R_bool r => encode (13, encode r)
    | R_list_PMA_Region r => encode (14, encode r)
    | R_option_bitvector_64 r => encode (15, encode r)
    | R_option_tuple__range_0_15_tdata r => encode (16, encode r)
    | R_option_tuple__range_3_31_event_csr r => encode (17, encode r)
    | R_vector_16_Trigger r => encode (18, encode r)
    | R_vector_32_bitvector_64 r => encode (19, encode r)
    | R_vector_64_bitvector_64 r => encode (20, encode r)
    | R_vector_64_bitvector_8 r => encode (21, encode r)
    | R_vector_64_option_TLB_Entry r => encode (22, encode r)
    end.
  Definition register_decode (x : positive) : option register :=
    match decode x with
    | Some (0, y) => r ← decode y; mret (R_HartState r)
    | Some (1, y) => r ← decode y; mret (R_Privilege r)
    | Some (2, y) => r ← decode y; mret (R_bitvector_1 r)
    | Some (3, y) => r ← decode y; mret (R_bitvector_128 r)
    | Some (4, y) => r ← decode y; mret (R_bitvector_192 r)
    | Some (5, y) => r ← decode y; mret (R_bitvector_3 r)
    | Some (6, y) => r ← decode y; mret (R_bitvector_32 r)
    | Some (7, y) => r ← decode y; mret (R_bitvector_320 r)
    | Some (8, y) => r ← decode y; mret (R_bitvector_4 r)
    | Some (9, y) => r ← decode y; mret (R_bitvector_5 r)
    | Some (10, y) => r ← decode y; mret (R_bitvector_64 r)
    | Some (11, y) => r ← decode y; mret (R_bitvector_704 r)
    | Some (12, y) => r ← decode y; mret (R_bitvector_exp_8 r)
    | Some (13, y) => r ← decode y; mret (R_bool r)
    | Some (14, y) => r ← decode y; mret (R_list_PMA_Region r)
    | Some (15, y) => r ← decode y; mret (R_option_bitvector_64 r)
    | Some (16, y) => r ← decode y; mret (R_option_tuple__range_0_15_tdata r)
    | Some (17, y) => r ← decode y; mret (R_option_tuple__range_3_31_event_csr r)
    | Some (18, y) => r ← decode y; mret (R_vector_16_Trigger r)
    | Some (19, y) => r ← decode y; mret (R_vector_32_bitvector_64 r)
    | Some (20, y) => r ← decode y; mret (R_vector_64_bitvector_64 r)
    | Some (21, y) => r ← decode y; mret (R_vector_64_bitvector_8 r)
    | Some (22, y) => r ← decode y; mret (R_vector_64_option_TLB_Entry r)
    | _ => None
    end.
  Lemma register_decode_encode r : register_decode (register_encode r) = Some r.
  Proof.
    destruct r;
    unfold register_decode, register_encode;
    rewrite !decode_encode;
    reflexivity.
  Qed.
  Lemma register_encode_inj r r' : register_encode r = register_encode r' -> r = r'.
  Proof.
    intro H.
    enough (Some r = Some r') by congruence.
    rewrite <- (register_decode_encode r).
    rewrite <- (register_decode_encode r').
    congruence.
  Qed.
  #[export] Instance Decidable_eq_register : EqDecision register.
  refine (fun r r' => match Pos.eq_dec (register_encode r) (register_encode r') with
  | left e => left (register_encode_inj _ _ e)
  | right ne => right _
  end).
  congruence.
  Defined.
  #[export] Instance Countable_register : Countable register := {|
    encode := register_encode;
    decode := register_decode;
    decode_encode := register_decode_encode;
  |}.

Definition register_transport {P : Type -> Type} {r r' : register} : r = r' -> P (type_of_register r) -> P (type_of_register r').
refine (
  match r, r' with
  | R_HartState r, R_HartState r' => fun _ x => x
  | R_Privilege r, R_Privilege r' => fun _ x => x
  | R_bitvector_1 r, R_bitvector_1 r' => fun _ x => x
  | R_bitvector_128 r, R_bitvector_128 r' => fun _ x => x
  | R_bitvector_192 r, R_bitvector_192 r' => fun _ x => x
  | R_bitvector_3 r, R_bitvector_3 r' => fun _ x => x
  | R_bitvector_32 r, R_bitvector_32 r' => fun _ x => x
  | R_bitvector_320 r, R_bitvector_320 r' => fun _ x => x
  | R_bitvector_4 r, R_bitvector_4 r' => fun _ x => x
  | R_bitvector_5 r, R_bitvector_5 r' => fun _ x => x
  | R_bitvector_64 r, R_bitvector_64 r' => fun _ x => x
  | R_bitvector_704 r, R_bitvector_704 r' => fun _ x => x
  | R_bitvector_exp_8 r, R_bitvector_exp_8 r' => fun _ x => x
  | R_bool r, R_bool r' => fun _ x => x
  | R_list_PMA_Region r, R_list_PMA_Region r' => fun _ x => x
  | R_option_bitvector_64 r, R_option_bitvector_64 r' => fun _ x => x
  | R_option_tuple__range_0_15_tdata r, R_option_tuple__range_0_15_tdata r' => fun _ x => x
  | R_option_tuple__range_3_31_event_csr r, R_option_tuple__range_3_31_event_csr r' => fun _ x => x
  | R_vector_16_Trigger r, R_vector_16_Trigger r' => fun _ x => x
  | R_vector_32_bitvector_64 r, R_vector_32_bitvector_64 r' => fun _ x => x
  | R_vector_64_bitvector_64 r, R_vector_64_bitvector_64 r' => fun _ x => x
  | R_vector_64_bitvector_8 r, R_vector_64_bitvector_8 r' => fun _ x => x
  | R_vector_64_option_TLB_Entry r, R_vector_64_option_TLB_Entry r' => fun _ x => x
  | _, _ => fun e _ => _
  end
).
  all:
  enough (H : type_of_register r0 = type_of_register r1);
  [ simpl in H; congruence
  | rewrite e; reflexivity].
Defined.

Lemma register_transport_sound {P} {r : register} (e : r = r) (p : P (type_of_register r)) :
  register_transport e p = p.
Proof.
  destruct r; reflexivity.
Qed.

Definition register_beq (r r' : register) : bool :=
  match r, r' with
  | R_HartState r, R_HartState r' => register_HartState_beq r r'
  | R_Privilege r, R_Privilege r' => register_Privilege_beq r r'
  | R_bitvector_1 r, R_bitvector_1 r' => register_bitvector_1_beq r r'
  | R_bitvector_128 r, R_bitvector_128 r' => register_bitvector_128_beq r r'
  | R_bitvector_192 r, R_bitvector_192 r' => register_bitvector_192_beq r r'
  | R_bitvector_3 r, R_bitvector_3 r' => register_bitvector_3_beq r r'
  | R_bitvector_32 r, R_bitvector_32 r' => register_bitvector_32_beq r r'
  | R_bitvector_320 r, R_bitvector_320 r' => register_bitvector_320_beq r r'
  | R_bitvector_4 r, R_bitvector_4 r' => register_bitvector_4_beq r r'
  | R_bitvector_5 r, R_bitvector_5 r' => register_bitvector_5_beq r r'
  | R_bitvector_64 r, R_bitvector_64 r' => register_bitvector_64_beq r r'
  | R_bitvector_704 r, R_bitvector_704 r' => register_bitvector_704_beq r r'
  | R_bitvector_exp_8 r, R_bitvector_exp_8 r' => register_bitvector_exp_8_beq r r'
  | R_bool r, R_bool r' => register_bool_beq r r'
  | R_list_PMA_Region r, R_list_PMA_Region r' => register_list_PMA_Region_beq r r'
  | R_option_bitvector_64 r, R_option_bitvector_64 r' => register_option_bitvector_64_beq r r'
  | R_option_tuple__range_0_15_tdata r, R_option_tuple__range_0_15_tdata r' => register_option_tuple__range_0_15_tdata_beq r r'
  | R_option_tuple__range_3_31_event_csr r, R_option_tuple__range_3_31_event_csr r' => register_option_tuple__range_3_31_event_csr_beq r r'
  | R_vector_16_Trigger r, R_vector_16_Trigger r' => register_vector_16_Trigger_beq r r'
  | R_vector_32_bitvector_64 r, R_vector_32_bitvector_64 r' => register_vector_32_bitvector_64_beq r r'
  | R_vector_64_bitvector_64 r, R_vector_64_bitvector_64 r' => register_vector_64_bitvector_64_beq r r'
  | R_vector_64_bitvector_8 r, R_vector_64_bitvector_8 r' => register_vector_64_bitvector_8_beq r r'
  | R_vector_64_option_TLB_Entry r, R_vector_64_option_TLB_Entry r' => register_vector_64_option_TLB_Entry_beq r r'
  | _, _ => false
  end.

Lemma register_beq_refl (r : register) : register_beq r r = true.
destruct r; simpl; autorewrite with register_beq_refls; reflexivity.
Qed.

Definition register_eq_cast (P : Type -> Type) (r r' : register) : P (type_of_register r) -> option (P (type_of_register r')) :=
  match r, r' with
  | R_HartState r, R_HartState r' => fun p => if register_HartState_beq r r' then Some p else None
  | R_Privilege r, R_Privilege r' => fun p => if register_Privilege_beq r r' then Some p else None
  | R_bitvector_1 r, R_bitvector_1 r' => fun p => if register_bitvector_1_beq r r' then Some p else None
  | R_bitvector_128 r, R_bitvector_128 r' => fun p => if register_bitvector_128_beq r r' then Some p else None
  | R_bitvector_192 r, R_bitvector_192 r' => fun p => if register_bitvector_192_beq r r' then Some p else None
  | R_bitvector_3 r, R_bitvector_3 r' => fun p => if register_bitvector_3_beq r r' then Some p else None
  | R_bitvector_32 r, R_bitvector_32 r' => fun p => if register_bitvector_32_beq r r' then Some p else None
  | R_bitvector_320 r, R_bitvector_320 r' => fun p => if register_bitvector_320_beq r r' then Some p else None
  | R_bitvector_4 r, R_bitvector_4 r' => fun p => if register_bitvector_4_beq r r' then Some p else None
  | R_bitvector_5 r, R_bitvector_5 r' => fun p => if register_bitvector_5_beq r r' then Some p else None
  | R_bitvector_64 r, R_bitvector_64 r' => fun p => if register_bitvector_64_beq r r' then Some p else None
  | R_bitvector_704 r, R_bitvector_704 r' => fun p => if register_bitvector_704_beq r r' then Some p else None
  | R_bitvector_exp_8 r, R_bitvector_exp_8 r' => fun p => if register_bitvector_exp_8_beq r r' then Some p else None
  | R_bool r, R_bool r' => fun p => if register_bool_beq r r' then Some p else None
  | R_list_PMA_Region r, R_list_PMA_Region r' => fun p => if register_list_PMA_Region_beq r r' then Some p else None
  | R_option_bitvector_64 r, R_option_bitvector_64 r' => fun p => if register_option_bitvector_64_beq r r' then Some p else None
  | R_option_tuple__range_0_15_tdata r, R_option_tuple__range_0_15_tdata r' => fun p => if register_option_tuple__range_0_15_tdata_beq r r' then Some p else None
  | R_option_tuple__range_3_31_event_csr r, R_option_tuple__range_3_31_event_csr r' => fun p => if register_option_tuple__range_3_31_event_csr_beq r r' then Some p else None
  | R_vector_16_Trigger r, R_vector_16_Trigger r' => fun p => if register_vector_16_Trigger_beq r r' then Some p else None
  | R_vector_32_bitvector_64 r, R_vector_32_bitvector_64 r' => fun p => if register_vector_32_bitvector_64_beq r r' then Some p else None
  | R_vector_64_bitvector_64 r, R_vector_64_bitvector_64 r' => fun p => if register_vector_64_bitvector_64_beq r r' then Some p else None
  | R_vector_64_bitvector_8 r, R_vector_64_bitvector_8 r' => fun p => if register_vector_64_bitvector_8_beq r r' then Some p else None
  | R_vector_64_option_TLB_Entry r, R_vector_64_option_TLB_Entry r' => fun p => if register_vector_64_option_TLB_Entry_beq r r' then Some p else None
  | _, _ => fun _ => None
  end.

Definition register_list : list (string * register) := List.concat [
  List.map (fun '(s, r) => (s, R_HartState r)) register_HartState_list;
  List.map (fun '(s, r) => (s, R_Privilege r)) register_Privilege_list;
  List.map (fun '(s, r) => (s, R_bitvector_1 r)) register_bitvector_1_list;
  List.map (fun '(s, r) => (s, R_bitvector_128 r)) register_bitvector_128_list;
  List.map (fun '(s, r) => (s, R_bitvector_192 r)) register_bitvector_192_list;
  List.map (fun '(s, r) => (s, R_bitvector_3 r)) register_bitvector_3_list;
  List.map (fun '(s, r) => (s, R_bitvector_32 r)) register_bitvector_32_list;
  List.map (fun '(s, r) => (s, R_bitvector_320 r)) register_bitvector_320_list;
  List.map (fun '(s, r) => (s, R_bitvector_4 r)) register_bitvector_4_list;
  List.map (fun '(s, r) => (s, R_bitvector_5 r)) register_bitvector_5_list;
  List.map (fun '(s, r) => (s, R_bitvector_64 r)) register_bitvector_64_list;
  List.map (fun '(s, r) => (s, R_bitvector_704 r)) register_bitvector_704_list;
  List.map (fun '(s, r) => (s, R_bitvector_exp_8 r)) register_bitvector_exp_8_list;
  List.map (fun '(s, r) => (s, R_bool r)) register_bool_list;
  List.map (fun '(s, r) => (s, R_list_PMA_Region r)) register_list_PMA_Region_list;
  List.map (fun '(s, r) => (s, R_option_bitvector_64 r)) register_option_bitvector_64_list;
  List.map (fun '(s, r) => (s, R_option_tuple__range_0_15_tdata r)) register_option_tuple__range_0_15_tdata_list;
  List.map (fun '(s, r) => (s, R_option_tuple__range_3_31_event_csr r)) register_option_tuple__range_3_31_event_csr_list;
  List.map (fun '(s, r) => (s, R_vector_16_Trigger r)) register_vector_16_Trigger_list;
  List.map (fun '(s, r) => (s, R_vector_32_bitvector_64 r)) register_vector_32_bitvector_64_list;
  List.map (fun '(s, r) => (s, R_vector_64_bitvector_64 r)) register_vector_64_bitvector_64_list;
  List.map (fun '(s, r) => (s, R_vector_64_bitvector_8 r)) register_vector_64_bitvector_8_list;
  List.map (fun '(s, r) => (s, R_vector_64_option_TLB_Entry r)) register_vector_64_option_TLB_Entry_list
].

Definition string_of_register (r : register) : string :=
  match List.find (fun '(_s, r') => register_beq r r') register_list with
  | Some (s, _r) => s
  | None => "<impossible>"
  end.

Instance Pretty_register : Pretty register :=
  fun reg => string_of_register reg.

Definition register_of_string (s : string) : option register :=
  match List.find (fun '(s', _r) => String.eqb s s') register_list with
  | Some (_s, r) => Some r
  | None => None
  end.

Lemma string_of_register_roundtrip (r : register) :
  register_of_string (string_of_register r) = Some r.
case r; intro r'; destruct r'; reflexivity.
Qed.

#[export] Instance string_of_register_inj : Inj (=) (=) string_of_register.
Proof.
  intros r r' H.
  specialize (string_of_register_roundtrip r) as H1.
  specialize (string_of_register_roundtrip r') as H2.
  rewrite H in H1.
  rewrite H2 in H1.
  congruence.
Qed.
#[export] Hint Extern 1 (register _) => assumption : typeclass_instances.
