  | R_vector_64_option_TLB_Entry _ => encode
  end;
  decode := match r with
  | R_HartState _ => decode
  | R_Privilege _ => decode
  | R_bitvector_1 _ => decode
  | R_bitvector_128 _ => decode
  | R_bitvector_192 _ => decode
  | R_bitvector_3 _ => decode
