  | R_option_tuple__range_3_31_event_csr _ => decode
  | R_vector_16_Trigger _ => decode
  | R_vector_32_bitvector_64 _ => decode
  | R_vector_64_bitvector_64 _ => decode
  | R_vector_64_bitvector_8 _ => decode
  | R_vector_64_option_TLB_Entry _ => decode
  end;
|}.
abstract (destruct r; apply decode_encode).
Defined.

