(* Definitions to support the lifting to the sequential monad *)
Record regstate := {
  HartState_s : register_HartState -> HartState;
  Privilege_s : register_Privilege -> Privilege;
  bitvector_1_s : register_bitvector_1 -> mword 1;
  bitvector_128_s : register_bitvector_128 -> mword 128;
  bitvector_192_s : register_bitvector_192 -> mword 192;
  bitvector_3_s : register_bitvector_3 -> mword 3;
  bitvector_32_s : register_bitvector_32 -> mword 32;
  bitvector_320_s : register_bitvector_320 -> mword 320;
  bitvector_4_s : register_bitvector_4 -> mword 4;
  bitvector_5_s : register_bitvector_5 -> mword 5;
  bitvector_64_s : register_bitvector_64 -> mword 64;
  bitvector_704_s : register_bitvector_704 -> mword 704;
  bitvector_exp_8_s : register_bitvector_exp_8 -> mword (2 ^ 8);
  bool_s : register_bool -> bool;
  list_PMA_Region_s : register_list_PMA_Region -> list PMA_Region;
  option_bitvector_64_s : register_option_bitvector_64 -> option (mword ((if 64 =? 32 then 34 else 64)));
  option_tuple__range_0_15_tdata_s : register_option_tuple__range_0_15_tdata -> option ((Z * tdata));
  option_tuple__range_3_31_event_csr_s : register_option_tuple__range_3_31_event_csr -> option ((Z * event_csr));
  vector_16_Trigger_s : register_vector_16_Trigger -> vec Trigger 16;
  vector_32_bitvector_64_s : register_vector_32_bitvector_64 -> vec (mword 64) 32;
  vector_64_bitvector_64_s : register_vector_64_bitvector_64 -> vec (mword 64) 64;
  vector_64_bitvector_8_s : register_vector_64_bitvector_8 -> vec (mword 8) 64;
  vector_64_option_TLB_Entry_s : register_vector_64_option_TLB_Entry -> vec (option TLB_Entry) (2 ^ 6);
}.
Notation "{[ r 'with' 'HartState_s' := e ]}" :=
  match r with Build_regstate _ (_ as f1) (_ as f2) (_ as f3) (_ as f4) (_ as f5) (_ as f6) (_ as f7) (_ as f8) (_ as f9) (_ as f10) (_ as f11) (_ as f12) (_ as f13) (_ as f14) (_ as f15) (_ as f16) (_ as f17) (_ as f18) (_ as f19) (_ as f20) (_ as f21) (_ as f22) =>
    Build_regstate e f1 f2 f3 f4 f5 f6 f7 f8 f9 f10 f11 f12 f13 f14 f15 f16 f17 f18 f19 f20 f21 f22
      end (at level 1).
