Definition register_lookup (reg : register) (rs : regstate) : type_of_register reg :=
  match reg with
  | R_HartState r => rs.(HartState_s) r
  | R_Privilege r => rs.(Privilege_s) r
  | R_bitvector_1 r => rs.(bitvector_1_s) r
  | R_bitvector_128 r => rs.(bitvector_128_s) r
  | R_bitvector_192 r => rs.(bitvector_192_s) r
  | R_bitvector_3 r => rs.(bitvector_3_s) r
  | R_bitvector_32 r => rs.(bitvector_32_s) r
  | R_bitvector_320 r => rs.(bitvector_320_s) r
  | R_bitvector_4 r => rs.(bitvector_4_s) r
  | R_bitvector_5 r => rs.(bitvector_5_s) r
  | R_bitvector_64 r => rs.(bitvector_64_s) r
  | R_bitvector_704 r => rs.(bitvector_704_s) r
  | R_bitvector_exp_8 r => rs.(bitvector_exp_8_s) r
  | R_bool r => rs.(bool_s) r
  | R_list_PMA_Region r => rs.(list_PMA_Region_s) r
  | R_option_bitvector_64 r => rs.(option_bitvector_64_s) r
  | R_option_tuple__range_0_15_tdata r => rs.(option_tuple__range_0_15_tdata_s) r
  | R_option_tuple__range_3_31_event_csr r => rs.(option_tuple__range_3_31_event_csr_s) r
  | R_vector_16_Trigger r => rs.(vector_16_Trigger_s) r
  | R_vector_32_bitvector_64 r => rs.(vector_32_bitvector_64_s) r
  | R_vector_64_bitvector_64 r => rs.(vector_64_bitvector_64_s) r
  | R_vector_64_bitvector_8 r => rs.(vector_64_bitvector_8_s) r
  | R_vector_64_option_TLB_Entry r => rs.(vector_64_option_TLB_Entry_s) r
  end.

Definition register_set (reg : register) : type_of_register reg -> regstate -> regstate :=
  match reg with
  | R_HartState r => fun v rs => {[ rs with HartState_s := fun r' => if register_HartState_beq r' r then v else rs.(HartState_s) r' ]}
  | R_Privilege r => fun v rs => {[ rs with Privilege_s := fun r' => if register_Privilege_beq r' r then v else rs.(Privilege_s) r' ]}
  | R_bitvector_1 r => fun v rs => {[ rs with bitvector_1_s := fun r' => if register_bitvector_1_beq r' r then v else rs.(bitvector_1_s) r' ]}
  | R_bitvector_128 r => fun v rs => {[ rs with bitvector_128_s := fun r' => if register_bitvector_128_beq r' r then v else rs.(bitvector_128_s) r' ]}
  | R_bitvector_192 r => fun v rs => {[ rs with bitvector_192_s := fun r' => if register_bitvector_192_beq r' r then v else rs.(bitvector_192_s) r' ]}
  | R_bitvector_3 r => fun v rs => {[ rs with bitvector_3_s := fun r' => if register_bitvector_3_beq r' r then v else rs.(bitvector_3_s) r' ]}
  | R_bitvector_32 r => fun v rs => {[ rs with bitvector_32_s := fun r' => if register_bitvector_32_beq r' r then v else rs.(bitvector_32_s) r' ]}
  | R_bitvector_320 r => fun v rs => {[ rs with bitvector_320_s := fun r' => if register_bitvector_320_beq r' r then v else rs.(bitvector_320_s) r' ]}
  | R_bitvector_4 r => fun v rs => {[ rs with bitvector_4_s := fun r' => if register_bitvector_4_beq r' r then v else rs.(bitvector_4_s) r' ]}
  | R_bitvector_5 r => fun v rs => {[ rs with bitvector_5_s := fun r' => if register_bitvector_5_beq r' r then v else rs.(bitvector_5_s) r' ]}
  | R_bitvector_64 r => fun v rs => {[ rs with bitvector_64_s := fun r' => if register_bitvector_64_beq r' r then v else rs.(bitvector_64_s) r' ]}
  | R_bitvector_704 r => fun v rs => {[ rs with bitvector_704_s := fun r' => if register_bitvector_704_beq r' r then v else rs.(bitvector_704_s) r' ]}
  | R_bitvector_exp_8 r => fun v rs => {[ rs with bitvector_exp_8_s := fun r' => if register_bitvector_exp_8_beq r' r then v else rs.(bitvector_exp_8_s) r' ]}
  | R_bool r => fun v rs => {[ rs with bool_s := fun r' => if register_bool_beq r' r then v else rs.(bool_s) r' ]}
  | R_list_PMA_Region r => fun v rs => {[ rs with list_PMA_Region_s := fun r' => if register_list_PMA_Region_beq r' r then v else rs.(list_PMA_Region_s) r' ]}
  | R_option_bitvector_64 r => fun v rs => {[ rs with option_bitvector_64_s := fun r' => if register_option_bitvector_64_beq r' r then v else rs.(option_bitvector_64_s) r' ]}
  | R_option_tuple__range_0_15_tdata r => fun v rs => {[ rs with option_tuple__range_0_15_tdata_s := fun r' => if register_option_tuple__range_0_15_tdata_beq r' r then v else rs.(option_tuple__range_0_15_tdata_s) r' ]}
  | R_option_tuple__range_3_31_event_csr r => fun v rs => {[ rs with option_tuple__range_3_31_event_csr_s := fun r' => if register_option_tuple__range_3_31_event_csr_beq r' r then v else rs.(option_tuple__range_3_31_event_csr_s) r' ]}
  | R_vector_16_Trigger r => fun v rs => {[ rs with vector_16_Trigger_s := fun r' => if register_vector_16_Trigger_beq r' r then v else rs.(vector_16_Trigger_s) r' ]}
  | R_vector_32_bitvector_64 r => fun v rs => {[ rs with vector_32_bitvector_64_s := fun r' => if register_vector_32_bitvector_64_beq r' r then v else rs.(vector_32_bitvector_64_s) r' ]}
  | R_vector_64_bitvector_64 r => fun v rs => {[ rs with vector_64_bitvector_64_s := fun r' => if register_vector_64_bitvector_64_beq r' r then v else rs.(vector_64_bitvector_64_s) r' ]}
  | R_vector_64_bitvector_8 r => fun v rs => {[ rs with vector_64_bitvector_8_s := fun r' => if register_vector_64_bitvector_8_beq r' r then v else rs.(vector_64_bitvector_8_s) r' ]}
  | R_vector_64_option_TLB_Entry r => fun v rs => {[ rs with vector_64_option_TLB_Entry_s := fun r' => if register_vector_64_option_TLB_Entry_beq r' r then v else rs.(vector_64_option_TLB_Entry_s) r' ]}
  end.

Lemma register_lookup_set (r : register) regs v: register_lookup r (register_set r v regs) = v.
destruct regs, r; simpl; autorewrite with register_beq_refls; reflexivity.
Qed.

Lemma irrelevant_register_set (r r' : register) regs v:
  register_beq r r' = false ->
  register_lookup r (register_set r' v regs) = register_lookup r regs.
destruct regs, r, r'; simpl; intro EQ; rewrite ?EQ; reflexivity.
Qed.

Arguments register_set : simpl never.
Arguments register_lookup : simpl never.

Definition register_accessors : register_accessors regstate register type_of_register := (@register_lookup, @register_set).


(* Instantiate library definitions with types. *)

Definition read_reg {E} := @read_reg register type_of_register E.
Definition write_reg {E} := @write_reg register type_of_register E.

Module Arch <: Arch.
  Definition reg : Type := register.
  #[global] Typeclasses Transparent reg.
  Definition reg_eq := @Decidable_eq_register.
  Definition reg_countable := @Countable_register.
  Definition reg_pretty := @Pretty_register.
  Definition reg_type := type_of_register.
  Definition reg_type_eq := @Decidable_eq_register_values.
  Definition reg_type_countable := @Countable_register_values.
  Definition reg_type_inhabited := @Inhabited_register_values.
  Definition regval_transport := @register_transport (fun x => x).
  Definition regval_transport_sound := @register_transport_sound (fun x => x).
  Definition addr_size : N := Z.to_N (physaddrbits_len).
  Definition addr_space : Type := unit.
  Definition addr_space_eq : EqDecision addr_space := _.
  Definition addr_space_countable : Countable addr_space := _.
  Definition mem_acc : Type := access_kind_typ.
  Definition mem_acc_eq : EqDecision mem_acc := _.
  Definition mem_acc_countable : Countable mem_acc := _.
  Definition CHERI : bool := (base_E_enabled).
  Definition cap_size_log : N := 0.
  Definition mem_acc_is_explicit := ak_is_explicit.
  Definition mem_acc_is_ifetch := ak_is_ifetch.
  Definition mem_acc_is_ttw := ak_is_ttw.
  Definition mem_acc_is_relaxed := ak_is_relaxed.
  Definition mem_acc_is_rel_acq_rcpc := ak_is_rel_acq_rcpc.
  Definition mem_acc_is_rel_acq_rcsc := ak_is_rel_acq_rcsc.
  Definition mem_acc_is_standalone := ak_is_standalone.
  Definition mem_acc_is_exclusive := ak_is_exclusive.
  Definition mem_acc_is_atomic_rmw := ak_is_atomic_rmw.
  Definition trans_start : Type := unit.
  Definition trans_start_eq : EqDecision trans_start := _.
  Definition trans_start_countable : Countable trans_start := _.
  Definition trans_end : Type := unit.
  Definition trans_end_eq : EqDecision trans_end := _.
  Definition trans_end_countable : Countable trans_end := _.
  Definition abort : Type := unit.
  Definition abort_eq : EqDecision abort := _.
  Definition abort_countable : Countable abort := _.
  Definition barrier : Type := barrier_kind.
  Definition barrier_eq : EqDecision barrier := _.
  Definition barrier_countable : Countable barrier := _.
  Definition cache_op : Type := unit.
  Definition cache_op_eq : EqDecision cache_op := _.
  Definition cache_op_countable : Countable cache_op := _.
  Definition tlbi : Type := unit.
  Definition tlbi_eq : EqDecision tlbi := _.
  Definition tlbi_countable : Countable tlbi := _.
  Definition exn : Type := unit.
  Definition exn_eq : EqDecision exn := _.
  Definition exn_countable : Countable exn := _.
  Definition sys_reg_id : Type := unit.
  Definition sys_reg_id_eq : EqDecision sys_reg_id := _.
  Definition sys_reg_id_countable : Countable sys_reg_id := _.
End Arch.

Module Interface := Interface Arch.
Module Defs := Defs Arch Interface.

Definition M := Defs.monad exception.
Definition MR r := Defs.monad (r + exception)%type.
Definition returnM {A:Type} : A -> M A := Defs.returnm (E := exception).
Definition returnR {A:Type} (R:Type) : A -> MR R A := Defs.returnm (E := R + exception)%type.
Definition register_ref := @register_ref register type_of_register.